// Cyrus engine core: the plan-tier gate for custom assets (MASTER-PLAN section 2, owner decisions).
//   free, katara -> no asset studios, no asset generation
//   saka         -> SOUND (Sound Studio + Sound Library)
//   all          -> SOUND + TEXTURE (the top plan; it includes the Yakko model)
// Tiers are cumulative. The gate applies only to CREATING or EDITING asset content (a studio, a library pick, an
// upload, or Cyrus generating it automatically inside a build). Keeping, installing, rebuilding unchanged,
// exporting, importing your own mod and composing Mod Packs are NEVER gated. An unknown plan or token state
// denies creation (fail closed) but never denies keep/install/export.
// Pure + client-safe; the server must call it again on every request (the UI check is only a hint).
import type { AssetKind, AssetSource, ModSpec } from "./spec";
import { ASSET_KINDS } from "./spec";

export const ASSET_PLANS = ["free", "katara", "saka", "all"] as const;
export type AssetPlan = (typeof ASSET_PLANS)[number];
const RANK: Record<AssetPlan, number> = { free: 0, katara: 1, saka: 2, all: 3 };
export const PLAN_LABEL: Record<AssetPlan, string> = { free: "Free", katara: "Katara", saka: "Saka", all: "All models" };

/**
 * THE one place that reconciles plan spellings. The token economy calls the top plan `all`
 * (lib/cyrus/tokens/config.ts TOKEN_TIERS); the UI and the model list call it after its top model, Yakko.
 * Anything else (null, a typo, a future plan) is unknown -> null, and callers fail closed.
 */
export function normalizePlan(raw: unknown): AssetPlan | null {
  if (typeof raw !== "string") return null;
  const v = raw.trim().toLowerCase();
  if (v === "all" || v === "yakko" || v === "all models") return "all";
  if (v === "free" || v === "katara" || v === "saka") return v;
  return null;
}

/** Plan from a token state (lib/cyrus/tokens/view.ts TokenState) or anything with a `tier`. Missing state -> null (unknown). */
export const planFromTokenState = (state: { tier?: unknown } | null | undefined): AssetPlan | null => normalizePlan(state?.tier);

/**
 * Cheapest plan that may create/edit each kind. `model` and `ui` are visual assets drawn with the texture tools,
 * so they follow the Texture Studio (top plan).
 */
export const ASSET_MIN_PLAN: Readonly<Record<AssetKind, AssetPlan>> = { sound: "saka", texture: "all", model: "all", ui: "all" };

export const ASSET_OPS = ["create", "edit", "keep", "install", "export", "rebuild", "import", "compose"] as const;
export type AssetOp = (typeof ASSET_OPS)[number];
export const GATED_OPS: readonly AssetOp[] = ["create", "edit"];

export type AssetDecision =
  | { ok: true }
  | { ok: false; code: "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: AssetPlan };

const KIND_WORD: Record<AssetKind, string> = { sound: "custom sounds", texture: "custom textures", model: "custom models", ui: "custom menu and HUD art" };

export function canAsset(plan: unknown, kind: AssetKind, op: AssetOp): AssetDecision {
  if (!(ASSET_OPS as readonly string[]).includes(op)) return { ok: false, code: "bad_request", reason: `unknown asset operation ${String(op)}` };
  if (!GATED_OPS.includes(op)) return { ok: true }; // keep / install / export / rebuild / import / compose: never gated
  if (!(ASSET_KINDS as readonly string[]).includes(kind)) return { ok: false, code: "bad_request", reason: `unknown asset kind ${String(kind)}` };
  const needs = ASSET_MIN_PLAN[kind];
  const p = normalizePlan(plan);
  if (!p) return { ok: false, code: "plan_unknown", needs, reason: `We couldn't confirm your Cyrus plan, so ${KIND_WORD[kind]} can't be created or edited right now.` };
  if (RANK[p] < RANK[needs]) return { ok: false, code: "asset_locked", needs, reason: `Creating or editing ${KIND_WORD[kind]} needs the ${PLAN_LABEL[needs]} plan or higher.` };
  return { ok: true };
}

/** What a spec asset slot asks the engine to do with asset content. */
export function assetOpForSource(source: AssetSource): AssetOp {
  switch (source) {
    case "generate": case "library": case "upload": return "create";
    case "edit": return "edit";
    case "existing": return "keep";
    case "imported": return "import";
    default: return "create"; // unknown source: treat as the gated case
  }
}

export type AssetDenial = { assetId: string; kind: AssetKind; code: "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: AssetPlan };

/** Every asset slot of a spec the plan may not create/edit (no changes). The build service request runs this too. */
export function gateSpecAssets(spec: Pick<ModSpec, "assets">, plan: unknown): AssetDenial[] {
  const out: AssetDenial[] = [];
  for (const a of spec.assets) {
    const d = canAsset(plan, a.kind, assetOpForSource(a.source));
    if (!d.ok) out.push({ assetId: a.id, kind: a.kind, code: d.code, reason: d.reason, ...(d.needs ? { needs: d.needs } : {}) });
  }
  return out;
}

const FALLBACK: Record<AssetKind, string> = { sound: "a vanilla sound", texture: "a vanilla look", model: "a vanilla model", ui: "plain text and standard menus" };

/**
 * Router downgrade: strip the gated asset slots instead of failing the build, with a customer-visible reason
 * per slot. Requirements stay (the mod still does what was asked, without the custom asset). Pure: returns a copy.
 */
export function downgradeSpecAssets<S extends Pick<ModSpec, "assets">>(spec: S, plan: unknown): { spec: S; removed: AssetDenial[]; notices: string[] } {
  const removed = gateSpecAssets(spec, plan);
  if (!removed.length) return { spec, removed, notices: [] };
  const drop = new Set(removed.map((r) => r.assetId));
  const notices = removed.map((r) => `${r.reason} Cyrus will build "${r.assetId}" with ${FALLBACK[r.kind]} instead.`);
  return { spec: { ...spec, assets: spec.assets.filter((a) => !drop.has(a.id)) }, removed, notices };
}
// Cyrus sound library (R1 sound slice): METADATA ONLY for the owner's sound-effect library. The audio itself never
// enters git, /opt/nxeon or any served directory: it lives on the render host (node-2) under
// /tank/nxeon-build/tmp/sound-library/files, keyed by the original file name and verified by sha256 before use.
// library.manifest.json is generated by scripts/cyrus/sound-manifest.ts from metadata scans done ON node-2
// (ffprobe + ffmpeg ebur128/astats, and the descriptors of ./descriptors.ts); classification = ./classify.ts applying
// ./taxonomy.json. Search lives in ./library-search.ts. Pure, no I/O beyond the JSON import.
//
// Ids: `<slug of the file name>_<first 4 hex of the content sha256>` (e.g. `whoosh_fast_2_3fa1`): readable for the
// model and for people, and bound to the bytes (a replaced file gets a new id, so old specs fail loudly).
import manifestJson from "./library.manifest.json";
import { categoryLabel, CATEGORY_IDS, stemOf, type Descriptors } from "./classify";
import type { RawDescriptors } from "./descriptors";

export { stemOf } from "./classify";
export const SOUND_LIBRARY_VERSION = 2;

export type SoundLedger = {
  provenance: string;
  /** Never asserts originality. The owner documents the source per file group (see manifest.source.licenceDocument). */
  licenceStatus: string;
};
export type LibrarySound = {
  id: string;
  file: string;
  /** the file-name prefix ("Whoosh", "Gunshot", "Door") */
  prefix: string;
  /** taxonomy category id (taxonomy.json), "other" only as a last resort */
  category: string;
  useCases: string[];
  /** why the file has no category / use case (owner review list) */
  unclassified?: string;
  tags: string[];
  descriptors: Descriptors;
  raw: RawDescriptors;
  /** seconds */
  duration: number;
  sampleRate: number;
  channels: number;
  bitRate: number;
  bytes: number;
  /** EBU R128 integrated loudness of the source (ffmpeg ebur128), LUFS */
  lufs: number | null;
  truePeakDb: number | null;
  samplePeakDb: number | null;
  rmsDb: number | null;
  dcOffset: number | null;
  sha256: string;
  ledger: SoundLedger;
};
export type SoundManifest = {
  version: number;
  generatedAt: string;
  taxonomyVersion: number;
  source: { description: string; zipSha256: string; uploadedAs: string; fileCount: number; licenceDocument: { name: string; sha256: string; licensor: string; summary: string[]; nxeonReading: string } };
  tool: string;
  files: LibrarySound[];
};

export const LEDGER_PROVENANCE = "owner-provided (2026-10-10)";
export const LEDGER_LICENCE_STATUS = "unverified: owner to document source per file group";

const slugWords = (s: string) => s.toLowerCase().replace(/['’]/g, "").split(/[^a-z0-9]+/).filter(Boolean);
/** Readable, content-bound id (see header). */
export function soundIdFor(file: string, sha256: string): string {
  const slug = slugWords(stemOf(file)).join("_").slice(0, 40).replace(/_+$/, "") || "sound";
  return `${/^[a-z]/.test(slug) ? slug : `s_${slug}`}_${sha256.slice(0, 4)}`;
}

const manifest = manifestJson as unknown as SoundManifest;
let byId: Map<string, LibrarySound> | null = null;
export function soundManifest(): SoundManifest { return manifest; }
export function librarySounds(): readonly LibrarySound[] { return manifest.files; }
export function librarySound(id: string): LibrarySound | null {
  if (!byId) byId = new Map(manifest.files.map((f) => [f.id, f]));
  return byId.get(id) ?? null;
}

/**
 * The compact catalog the build service places (read-only) in the model's workspace: ids, category, use cases and
 * duration class only (no audio, no file names, no loudness). Grouped by category; stable order so it caches.
 * services/modbuilder/sound-catalog.txt is this text for the current manifest (a test keeps them equal).
 */
export function libraryCatalogText(files: readonly LibrarySound[] = manifest.files): string {
  const lines = [
    "# Nxeon sound library catalog (read-only). One sound per line: <id> <duration class> <use cases>.",
    "# Duration classes: stinger < 0.5 s, short < 2 s, medium < 6 s, long. Use an id as a layer source: {\"source\": \"lib:<id>\"} and trim with \"length\".",
  ];
  for (const c of CATEGORY_IDS) {
    const xs = files.filter((f) => f.category === c).sort((a, b) => (a.id < b.id ? -1 : 1));
    if (!xs.length) continue;
    lines.push(`## ${categoryLabel(c)}`);
    for (const f of xs) lines.push(`${f.id} ${f.descriptors.durationClass}${f.useCases.length ? ` ${f.useCases.join(",")}` : ""}`);
  }
  return lines.join("\n") + "\n";
}

/** The machine-readable catalog for validators: id -> duration in seconds (the service's sound-catalog.json). */
export function libraryCatalogDurations(files: readonly LibrarySound[] = manifest.files): Record<string, number> {
  const out: Record<string, number> = {};
  for (const f of [...files].sort((a, b) => (a.id < b.id ? -1 : 1))) out[f.id] = Math.round(f.duration * 1000) / 1000;
  return out;
}
// Search over the sound library manifest (pure, client-safe; the Sound Studio library browser and the AI helpers use
// it). Free text with synonym expansion (taxonomy.json querySynonyms + synonyms) and ranking
//   exact tag (5, 4 via a synonym) > use case / category (3) > tag prefix (2) > file-name words (1)
// where EVERY query word must match something; facets and filters; pagination; and `similarTo`.
import { categoryLabel, canonicalWords, stemOf, TAXONOMY, type Descriptors } from "./classify";
import { librarySound, librarySounds, type LibrarySound } from "./library";

export type LibraryFilters = {
  category?: string | string[]; useCase?: string | string[]; tags?: string[];
  durationClass?: Descriptors["durationClass"][]; intensity?: Descriptors["intensity"][]; pitchBand?: Descriptors["pitchBand"][]; character?: Descriptors["character"][];
  loopable?: boolean; minDuration?: number; maxDuration?: number;
};
export type LibraryQuery = LibraryFilters & { text?: string; limit?: number; offset?: number };
export type Facets = { category: Record<string, number>; useCase: Record<string, number>; durationClass: Record<string, number>; intensity: Record<string, number>; pitchBand: Record<string, number> };
export type SearchResult = { total: number; items: LibrarySound[]; facets: Facets; expanded: string[][] };

const arr = <T>(v: T | T[] | undefined) => (v == null ? null : Array.isArray(v) ? v : [v]);

/** The terms one query word stands for: itself, its canonical form, and the query synonyms (one level, plus nested aliases). */
export function expandWord(w: string): string[] {
  const out = new Set<string>([w]);
  const canon = TAXONOMY.synonyms[w]; if (canon) out.add(canon);
  for (const x of [w, canon].filter(Boolean) as string[]) for (const s of TAXONOMY.querySynonyms[x] ?? []) { out.add(s); for (const t of TAXONOMY.querySynonyms[s] ?? []) out.add(t); }
  return [...out];
}

function matchesFilters(s: LibrarySound, f: LibraryFilters): boolean {
  const cats = arr(f.category), ucs = arr(f.useCase);
  if (cats && !cats.includes(s.category)) return false;
  if (ucs && !ucs.some((u) => s.useCases.includes(u))) return false;
  if (f.tags && f.tags.some((t) => !s.tags.includes(t.toLowerCase()))) return false;
  if (f.durationClass && !f.durationClass.includes(s.descriptors.durationClass)) return false;
  if (f.intensity && !f.intensity.includes(s.descriptors.intensity)) return false;
  if (f.pitchBand && !f.pitchBand.includes(s.descriptors.pitchBand)) return false;
  if (f.character && !f.character.includes(s.descriptors.character)) return false;
  if (f.loopable != null && s.descriptors.loopable !== f.loopable) return false;
  if (f.minDuration != null && s.duration < f.minDuration) return false;
  if (f.maxDuration != null && s.duration > f.maxDuration) return false;
  return true;
}

function scoreWord(s: LibrarySound, word: string, terms: string[], name: string[]): number {
  let best = 0;
  for (const t of terms) {
    const self = t === word || t === TAXONOMY.synonyms[word];
    if (s.tags.includes(t)) best = Math.max(best, self ? 5 : 4);
    else if (s.useCases.includes(t) || s.category === t || categoryLabel(s.category).toLowerCase() === t) best = Math.max(best, 3);
    else if (t.length >= 3 && s.tags.some((x) => x.startsWith(t))) best = Math.max(best, 2);
    else if (name.some((n) => n.includes(t))) best = Math.max(best, 1);
  }
  return best;
}

export function searchLibrary(q: LibraryQuery, files: readonly LibrarySound[] = librarySounds()): SearchResult {
  const qWords = canonicalWords(q.text ?? "").filter((w) => !TAXONOMY.stopWords.includes(w));
  const expanded = qWords.map(expandWord);
  const scored: { s: LibrarySound; score: number }[] = [];
  for (const s of files) {
    if (!matchesFilters(s, q)) continue;
    const name = canonicalWords(stemOf(s.file));
    let score = 0, miss = false;
    for (const [i, w] of qWords.entries()) { const v = scoreWord(s, w, expanded[i], name); if (!v) { miss = true; break; } score += v; }
    if (!miss) scored.push({ s, score });
  }
  scored.sort((a, b) => b.score - a.score || a.s.duration - b.s.duration || (a.s.id < b.s.id ? -1 : 1));
  const facets: Facets = { category: {}, useCase: {}, durationClass: {}, intensity: {}, pitchBand: {} };
  for (const { s } of scored) {
    facets.category[s.category] = (facets.category[s.category] ?? 0) + 1;
    for (const u of s.useCases) facets.useCase[u] = (facets.useCase[u] ?? 0) + 1;
    facets.durationClass[s.descriptors.durationClass] = (facets.durationClass[s.descriptors.durationClass] ?? 0) + 1;
    facets.intensity[s.descriptors.intensity] = (facets.intensity[s.descriptors.intensity] ?? 0) + 1;
    facets.pitchBand[s.descriptors.pitchBand] = (facets.pitchBand[s.descriptors.pitchBand] ?? 0) + 1;
  }
  const off = Math.max(0, q.offset ?? 0), lim = Math.min(200, Math.max(1, q.limit ?? 50));
  return { total: scored.length, items: scored.slice(off, off + lim).map((x) => x.s), facets, expanded };
}

/** Sounds like this one: same category, shared use cases, close descriptors and duration (most similar first). */
export function similarTo(id: string, limit = 10, files: readonly LibrarySound[] = librarySounds()): LibrarySound[] {
  const me = librarySound(id) ?? files.find((f) => f.id === id);
  if (!me) return [];
  const d = me.descriptors;
  return files.filter((f) => f.id !== me.id).map((f) => {
    let s = 0;
    if (f.category === me.category) s += 4;
    s += 2 * f.useCases.filter((u) => me.useCases.includes(u)).length;
    if (f.descriptors.durationClass === d.durationClass) s += 1;
    if (f.descriptors.pitchBand === d.pitchBand) s += 1;
    if (f.descriptors.intensity === d.intensity) s += 1;
    if (f.descriptors.character === d.character) s += 1;
    s -= Math.min(2, Math.abs(Math.log2((f.duration + 0.05) / (me.duration + 0.05))));
    return { f, s };
  }).filter((x) => x.s >= 4).sort((a, b) => b.s - a.s || (a.f.id < b.f.id ? -1 : 1)).slice(0, limit).map((x) => x.f);
}
// Apply the sound taxonomy (taxonomy.json: data, not code) to one library file: category, use cases, tags and the
// descriptor classes from the measured audio. Pure and deterministic; scripts/cyrus/sound-manifest.ts stores the
// result in the manifest and test/cyrus-sounds.test.ts re-derives every entry with it.
import taxonomyJson from "./taxonomy.json";
import type { RawDescriptors } from "./descriptors";

type Taxonomy = {
  version: number;
  synonyms: Record<string, string>;
  querySynonyms: Record<string, string[]>;
  categories: { id: string; label: string; keywords: string[] }[];
  useCases: { id: string; keywords: string[]; broader: string[] }[];
  descriptors: {
    durationClass: { id: string; maxSeconds: number }[];
    intensity: { softBelowLufs: number; loudFromLufs: number; loudPeakDb: number; loudPeakMinLufs: number };
    pitchBand: { lowBelowHz: number; highFromHz: number };
    character: { transientFrontEnergy: number; transientAttackMs: number; transientCrestDb: number };
    loopable: { maxStartEndDiffDb: number; minEdgeDb: number; minSeconds: number };
  };
  stopWords: string[];
};
export const TAXONOMY = taxonomyJson as unknown as Taxonomy;
export const CATEGORY_IDS = [...TAXONOMY.categories.map((c) => c.id), "other"];
export const USE_CASE_IDS = TAXONOMY.useCases.map((u) => u.id);
export const categoryLabel = (id: string) => TAXONOMY.categories.find((c) => c.id === id)?.label ?? "Other";

export type Descriptors = {
  durationClass: "stinger" | "short" | "medium" | "long";
  intensity: "soft" | "medium" | "loud";
  pitchBand: "low" | "mid" | "high";
  character: "transient" | "sustained";
  /** HEURISTIC: start and end levels match (could loop without an obvious seam); never verified by ear */
  loopable: boolean;
  channels: number;
};
export type Classification = { prefix: string; category: string; useCases: string[]; unclassified?: string; tags: string[]; descriptors: Descriptors };
export type AudioFacts = { duration: number; channels: number; lufs: number | null; samplePeakDb: number | null; raw: RawDescriptors };

export const stemOf = (file: string) => file.replace(/(\.mp3)+$/i, "");
const rawWords = (s: string) => s.toLowerCase().replace(/['’]/g, "").split(/[^a-z0-9]+/).filter(Boolean);
/** File-name words, canonicalised through the synonym table (swoosh -> whoosh, gunshots -> gunshot, ...). */
export const canonicalWords = (s: string) => rawWords(s).map((w) => TAXONOMY.synonyms[w] ?? w);

export function describe(a: AudioFacts): Descriptors {
  const d = TAXONOMY.descriptors;
  const durationClass = d.durationClass.find((c) => a.duration < c.maxSeconds)!.id as Descriptors["durationClass"];
  const lufs = a.lufs ?? -99, peak = a.samplePeakDb ?? -99;
  const intensity = lufs < d.intensity.softBelowLufs ? "soft" : lufs >= d.intensity.loudFromLufs || (peak >= d.intensity.loudPeakDb && lufs >= d.intensity.loudPeakMinLufs) ? "loud" : "medium";
  const pitchBand = a.raw.centroidHz < d.pitchBand.lowBelowHz ? "low" : a.raw.centroidHz >= d.pitchBand.highFromHz ? "high" : "mid";
  const c = d.character;
  const character = a.raw.frontEnergy >= c.transientFrontEnergy || (a.raw.attackMs < c.transientAttackMs && a.raw.crestDb >= c.transientCrestDb) ? "transient" : "sustained";
  const l = d.loopable;
  const loopable = a.duration >= l.minSeconds && a.raw.startDb > l.minEdgeDb && a.raw.endDb > l.minEdgeDb && Math.abs(a.raw.startDb - a.raw.endDb) <= l.maxStartEndDiffDb;
  return { durationClass, intensity, pitchBand, character, loopable, channels: a.channels };
}

export function classify(file: string, a: AudioFacts): Classification {
  const stem = stemOf(file);
  const head = stem.split(" - ")[0].replace(/\s*\d+\s*$/, "").trim();
  const prefix = head.replace(/-/g, " ").replace(/\s+/g, " ").split(" ").map((w) => (w ? w[0].toUpperCase() + w.slice(1).toLowerCase() : w)).join(" ") || "Misc";
  const headW = canonicalWords(head), all = canonicalWords(stem).filter((w) => !/^\d+x?$/.test(w));
  const hit = (ws: string[], kw: string[]) => ws.some((w) => kw.includes(w));
  const cat = TAXONOMY.categories.find((c) => hit(headW, c.keywords)) ?? TAXONOMY.categories.find((c) => hit(all, c.keywords));
  const useCases = TAXONOMY.useCases.filter((u) => hit(all, u.keywords)).map((u) => u.id);
  const broader = [...new Set(TAXONOMY.useCases.filter((u) => useCases.includes(u.id)).flatMap((u) => u.broader))];
  const stop = new Set(TAXONOMY.stopWords);
  const category = cat?.id ?? "other";
  const tags = [...new Set([...all.filter((w) => !stop.has(w) && w.length > 1), ...broader])].slice(0, 14);
  return {
    prefix, category, useCases,
    ...(cat ? {} : { unclassified: `no category keyword in "${stem}"` }),
    ...(useCases.length ? {} : { unclassified: `${cat ? "" : `no category keyword in "${stem}"; `}no use-case keyword in "${stem}"` }),
    tags, descriptors: describe(a),
  };
}
// Measured audio descriptors for the sound library (Cyrus R1 sound slice). Pure DSP on mono PCM; run ON node-2 over
// the library by scripts/cyrus/sound-descriptors.ts (the audio never leaves the render host), the raw numbers are
// committed in the manifest and turned into classes by the thresholds in taxonomy.json (classify.ts).
import { linToDb, SAMPLE_RATE, type Mono } from "./dsp";

export type RawDescriptors = {
  /** mean spectral centroid (Hz) over the louder frames */
  centroidHz: number;
  /** ms from the start to the loudest 10 ms window */
  attackMs: number;
  /** share of the energy in the first 25 % of the sound (high = a sharp transient that dies away) */
  frontEnergy: number;
  /** RMS (dBFS) of the first / last 50 ms (loop heuristic) */
  startDb: number;
  endDb: number;
  /** crest factor (peak / RMS, dB) */
  crestDb: number;
};

/** In-place iterative radix-2 FFT (re/im of length 2^k). */
function fft(re: Float64Array, im: Float64Array) {
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) { [re[i], re[j]] = [re[j], re[i]]; [im[i], im[j]] = [im[j], im[i]]; }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len, wr = Math.cos(ang), wi = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let cr = 1, ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k, b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci, ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr; im[b] = im[a] - ti; re[a] += tr; im[a] += ti;
        const nr = cr * wr - ci * wi; ci = cr * wi + ci * wr; cr = nr;
      }
    }
  }
}

const rms = (x: Mono, a: number, b: number) => { let s = 0; const e = Math.min(x.length, b); for (let i = a; i < e; i++) s += x[i] * x[i]; return e > a ? Math.sqrt(s / (e - a)) : 0; };
const r1 = (v: number) => (Number.isFinite(v) ? Math.round(v * 10) / 10 : -999);

export function rawDescriptors(x: Mono, fs = SAMPLE_RATE): RawDescriptors {
  const N = 2048, hop = 2048;
  const frames: { e: number; c: number }[] = [];
  const win = new Float64Array(N).map((_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (N - 1)));
  for (let a = 0; a + N <= x.length && frames.length < 400; a += hop) {
    const re = new Float64Array(N), im = new Float64Array(N);
    for (let i = 0; i < N; i++) re[i] = x[a + i] * win[i];
    fft(re, im);
    let num = 0, den = 0;
    for (let k = 1; k < N / 2; k++) { const m = Math.hypot(re[k], im[k]); num += m * ((k * fs) / N); den += m; }
    frames.push({ e: den, c: den > 0 ? num / den : 0 });
  }
  const maxE = Math.max(0, ...frames.map((f) => f.e));
  const loud = frames.filter((f) => f.e >= maxE * 0.1);
  const centroidHz = loud.length ? loud.reduce((s, f) => s + f.c * f.e, 0) / loud.reduce((s, f) => s + f.e, 0) : 0;
  const w = Math.round(0.01 * fs);
  let best = 0, bestAt = 0;
  for (let a = 0; a < x.length; a += w) { const v = rms(x, a, a + w); if (v > best) { best = v; bestAt = a; } }
  let total = 0, front = 0;
  const q = Math.floor(x.length / 4);
  let peak = 0;
  for (let i = 0; i < x.length; i++) { const e = x[i] * x[i]; total += e; if (i < q) front += e; peak = Math.max(peak, Math.abs(x[i])); }
  const allRms = x.length ? Math.sqrt(total / x.length) : 0;
  const t50 = Math.round(0.05 * fs);
  return {
    centroidHz: Math.round(centroidHz), attackMs: Math.round((bestAt / fs) * 1000), frontEnergy: total > 0 ? Math.round((front / total) * 1000) / 1000 : 0,
    startDb: r1(linToDb(rms(x, 0, t50))), endDb: r1(linToDb(rms(x, Math.max(0, x.length - t50), x.length))), crestDb: r1(linToDb(peak) - linToDb(allRms)),
  };
}
