// Cyrus engine core: the pure half of the revision store (file manifests, diffs, engine records).
// A revision's file manifest lists every file of the mod project at that revision as { path, sha256, role }.
// Pure + client-safe; the DB half is lib/cyrus/engine-core/store.ts.
import type { SpecIssue } from "./spec";

export const REVISION_KINDS = ["generated", "edited", "imported", "asset", "revert"] as const;
export type RevisionKind = (typeof REVISION_KINDS)[number];
export const REVISION_STATUSES = ["pending", "passed", "failed"] as const;
export type RevisionStatus = (typeof REVISION_STATUSES)[number];

export const FILE_ROLES = ["source", "resource", "config", "asset", "resourcePack", "dataPack", "test", "doc", "artifact", "other"] as const;
export type FileRole = (typeof FILE_ROLES)[number];
export type ManifestEntry = { path: string; sha256: string; role: FileRole };
export const MAX_MANIFEST_FILES = 5000;

const SHA256 = /^[0-9a-f]{64}$/;

/** A safe project-relative path: forward slashes, no leading slash, no empty / "." / ".." segments, no control chars. */
export function isSafeProjectPath(p: unknown): p is string {
  if (typeof p !== "string" || p.length === 0 || p.length > 512) return false;
  if (p.startsWith("/") || p.includes("\\") || /[\u0000-\u001f]/.test(p)) return false;
  return p.split("/").every((s) => s.length > 0 && s !== "." && s !== "..");
}

export type ManifestResult = { ok: true; entries: ManifestEntry[] } | { ok: false; errors: SpecIssue[] };

/** Untrusted manifest -> entries sorted by path (a stable order, so equal manifests serialise identically). */
export function validateManifest(raw: unknown): ManifestResult {
  if (!Array.isArray(raw)) return { ok: false, errors: [{ path: "manifest", code: "not_array", message: "manifest must be an array" }] };
  if (raw.length > MAX_MANIFEST_FILES) return { ok: false, errors: [{ path: "manifest", code: "too_many_files", message: `at most ${MAX_MANIFEST_FILES} files` }] };
  const errors: SpecIssue[] = [];
  const seen = new Set<string>();
  const entries: ManifestEntry[] = [];
  raw.forEach((e, i) => {
    const at = `manifest[${i}]`;
    const r = (e ?? {}) as Record<string, unknown>;
    if (!isSafeProjectPath(r.path)) { errors.push({ path: `${at}.path`, code: "bad_path", message: "path must be a safe relative path" }); return; }
    if (typeof r.sha256 !== "string" || !SHA256.test(r.sha256)) errors.push({ path: `${at}.sha256`, code: "bad_sha256", message: "sha256 must be 64 lowercase hex characters" });
    if (!(FILE_ROLES as readonly string[]).includes(r.role as string)) errors.push({ path: `${at}.role`, code: "bad_role", message: `role must be one of ${FILE_ROLES.join(", ")}` });
    if (seen.has(r.path)) errors.push({ path: `${at}.path`, code: "duplicate_path", message: `${r.path} is listed twice` });
// Portal half of the texture specs a build returns (Cyrus R1). The build service already validated them with its JS
// copy (services/modbuilder/textures.js); the portal NEVER trusts that: it re-validates with lib/cyrus/textures,
// renders, runs the quality bar and identifies each spec by the sha256 of its canonical JSON (same bytes on both sides).
import { createHash } from "node:crypto";
import { checkSpec, type TextureSpec } from "../textures/dsl";
import { encodePng } from "../textures/png";
import { render } from "../textures/render";
import { qualityProblems, textureQuality, type QualityReport } from "../textures/quality";

/** Sorted keys at every level; the JS twin is services/modbuilder/textures.js canonicalJson. */
export function canonicalJson(v: unknown): string {
  if (Array.isArray(v)) return `[${v.map(canonicalJson).join(",")}]`;
  if (v && typeof v === "object") return `{${Object.keys(v).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson((v as Record<string, unknown>)[k])}`).join(",")}}`;
  return JSON.stringify(v);
}
export const sha256Hex = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
export const specSha256 = (spec: TextureSpec) => sha256Hex(canonicalJson(spec));

export type CheckedTexture =
  | { ok: true; name: string; spec: TextureSpec; specSha256: string; canonical: string; png: Buffer; pngSha256: string; quality: QualityReport }
  | { ok: false; name: string; reason: string; quality?: QualityReport };

/** Validate + render + quality one returned texture. A failing quality verdict is refused (never shipped). */
export function checkReturnedTexture(t: { name?: unknown; spec?: unknown }): CheckedTexture {
  const name = typeof t.name === "string" ? t.name : "?";
  const c = checkSpec(t.spec);
  if (!c.ok) return { ok: false, name, reason: c.error };
  if (c.spec.name !== name) return { ok: false, name, reason: `spec name ${c.spec.name} does not match ${name}` };
  const raster = render(c.spec);
  const quality = textureQuality(raster);
  if (quality.verdict === "fail") return { ok: false, name, reason: qualityProblems(quality)[0] ?? "failed the texture checks", quality };
  const png = encodePng(raster);
  const canonical = canonicalJson(c.spec);
  return { ok: true, name, spec: c.spec, specSha256: sha256Hex(canonical), canonical, png, pngSha256: sha256Hex(png), quality };
}
