// Texture library templates -> plain DSL TextureSpecs (pure, client-safe, deterministic).
// A template is ORIGINAL pixel art authored in ./templates.ts as a character grid whose characters name RAMP SLOTS
// (not colours): '1'-'5' = the primary ramp m (1 darkest), 'a'-'e' = the secondary ramp h, 'p'-'t' = the accent
// ramp x, plus a few fixed colours per template. Choosing ramps from the Style DNA presets (taxonomy.json) turns one
// shape into many materials; the Style DNA preset decides the outline (an `outline` op at the end) and grain.
// The output is an ordinary TextureSpec: rect runs (merged vertically) in the existing DSL, so it passes checkSpec,
// renders with lib/cyrus/textures/render.ts and can be edited by the studio or the model like any other spec.
import taxonomyJson from "./taxonomy.json";
import { checkSpec, MAX_OPS, type Op, type TextureSpec } from "../textures/dsl";
import type { QualityProfile } from "../textures/quality";

export type Ramp = { id: string; label: string; family: string; shades: [string, string, string, string, string] };
export type OutlineRule = "tinted" | "black" | "none";
export type DnaPreset = { id: string; label: string; outline: OutlineRule; light: "top_left"; noise: string; rampSteps: number; note: string };
export type TextureTaxonomy = {
  version: number;
  categories: { id: string; label: string; subcategories: { id: string; label: string; keywords: string[]; uvNotes?: string }[] }[];
  useCases: { id: string; label: string; broader: string[] }[];
  styleDna: { lightDirections: string[]; outlineRules: { id: OutlineRule; label: string; note: string }[]; noiseLevels: { id: string; amount: number; note: string }[]; presets: DnaPreset[]; ramps: Ramp[] };
  ledger: { fields: string[]; builtinProvenance: string; builtinLicence: string; builtinLicenceStatus: string; originalRule: string };
  synonyms: Record<string, string>;
  querySynonyms: Record<string, string[]>;
  stopWords: string[];
};
export const TEXTURE_TAXONOMY = taxonomyJson as unknown as TextureTaxonomy;
export const TOP_CATEGORIES = TEXTURE_TAXONOMY.categories.map((c) => c.id);
export const SUBCATEGORIES = TEXTURE_TAXONOMY.categories.flatMap((c) => c.subcategories.map((s) => `${c.id}/${s.id}`));
export const TEXTURE_USE_CASES = TEXTURE_TAXONOMY.useCases.map((u) => u.id);
export const DEFAULT_DNA = "pixel_classic";

const rampById = new Map(TEXTURE_TAXONOMY.styleDna.ramps.map((r) => [r.id, r]));
export const ramp = (id: string): Ramp | null => rampById.get(id) ?? null;
export const ramps = (): readonly Ramp[] => TEXTURE_TAXONOMY.styleDna.ramps;
export const dnaPreset = (id: string): DnaPreset | null => TEXTURE_TAXONOMY.styleDna.presets.find((p) => p.id === id) ?? null;
const noiseAmount = (id: string) => TEXTURE_TAXONOMY.styleDna.noiseLevels.find((n) => n.id === id)?.amount ?? 0;

export const SLOT_KEYS = ["m", "h", "x"] as const;
export type SlotKey = (typeof SLOT_KEYS)[number];
const SLOT_CHARS: Record<SlotKey, string> = { m: "12345", h: "abcde", x: "pqrst" };
/** Fixed-colour characters a template may define (palette key = "f" + char). 'k' is the explicit outline colour. */
export const FIXED_CHARS = "uvwyzk";

export type TemplateVariant = Partial<Record<SlotKey, string>>;
export type TextureTemplate = {
  id: string;
  name: string;
  category: string;
  sub: string;
  useCases: string[];
  tags: string[];
  size: 16 | 32 | 64;
  profile: QualityProfile;
  tileable: boolean;
  /** Ramp FAMILIES each used slot accepts (a project may pick any ramp of that family). */
  slots: Partial<Record<SlotKey, string[]>>;
  /** The library variants (one library item each); the first is the template's default. */
  variants: TemplateVariant[];
  fixed?: Record<string, string>;
  /** Items get the DNA outline; tiles and swatches never do. */
  outline: boolean;
  grid: string[];
  note?: string;
};

export type InstantiateOptions = { name?: string; ramps?: TemplateVariant; dna?: string | DnaPreset };
export type Instantiated = { ok: true; spec: TextureSpec; ramps: Record<SlotKey, string | null>; dna: string } | { ok: false; error: string };

/** Darken a hex colour until its relative luminance is at or below `max` (outline colours read as outlines). */
export function darkenTo(hex: string, max = 0.08): string {
  let [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
  const lin = (c: number) => { const s = c / 255; return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4); };
  const lum = () => 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
  // start at 70 % so even a dark shade gets visibly darker than the ramp's own darkest (the outline must separate)
  r = Math.round(r * 0.7); g = Math.round(g * 0.7); b = Math.round(b * 0.7);
  for (let i = 0; i < 40 && lum() > max; i++) { r = Math.round(r * 0.85); g = Math.round(g * 0.85); b = Math.round(b * 0.85); }
  return `#${[r, g, b].map((v) => v.toString(16).padStart(2, "0")).join("")}`;
}

/** Grid -> rect ops: horizontal runs per row, then identical runs on consecutive rows merged into one taller rect. */
export function gridOps(grid: string[], keyOf: (ch: string) => string | null): Op[] {
  type Run = { x: number; y: number; w: number; h: number; c: string };
  const open = new Map<string, Run>(); // "x|w|c" -> run still growing downwards
  const done: Run[] = [];
  grid.forEach((row, y) => {
    const seen = new Set<string>();
    for (let x = 0; x < row.length; ) {
      const ch = row[x]; let e = x + 1;
      while (e < row.length && row[e] === ch) e++;
      const c = keyOf(ch);
      if (c) {
        const k = `${x}|${e - x}|${c}`; seen.add(k);
        const r = open.get(k);
        if (r && r.y + r.h === y) r.h++; else { if (r) done.push(r); open.set(k, { x, y, w: e - x, h: 1, c }); }
      }
      x = e;
    }
    for (const [k, r] of open) if (!seen.has(k)) { done.push(r); open.delete(k); }
  });
  done.push(...open.values());
  done.sort((a, b) => a.y - b.y || a.x - b.x);
  return done.map((r) => ({ op: "rect", x: r.x, y: r.y, w: r.w, h: r.h, c: r.c }));
}

/** Structural check of a template (grid shape, characters, slots, variants); the tests run it on every template. */
export function checkTemplate(t: TextureTemplate): string[] {
  const errs: string[] = [];
  if (!/^[a-z][a-z0-9_]{1,23}$/.test(t.id)) errs.push(`${t.id}: bad id`);
  if (t.grid.length !== t.size || t.grid.some((r) => r.length !== t.size)) errs.push(`${t.id}: grid must be ${t.size}x${t.size}`);
  const used = new Set(t.grid.join(""));
  for (const ch of used) {
    if (ch === ".") continue;
    const slot = SLOT_KEYS.find((s) => SLOT_CHARS[s].includes(ch));
    if (slot) { if (!t.slots[slot]) errs.push(`${t.id}: uses '${ch}' but has no ${slot} slot`); continue; }
