}

/**
 * Instantiate a template: pick ramps (default: the template's first variant; a project may choose any ramp of an
 * allowed family) and a Style DNA preset (outline rule + grain), and return a validated TextureSpec.
 */
export function instantiate(t: TextureTemplate, opts: InstantiateOptions = {}): Instantiated {
  const dna = typeof opts.dna === "object" && opts.dna ? opts.dna : dnaPreset((opts.dna as string | undefined) ?? DEFAULT_DNA);
  if (!dna) return { ok: false, error: `unknown Style DNA preset ${String(opts.dna)}` };
  const base = t.variants[0];
  const chosen: Record<SlotKey, string | null> = { m: null, h: null, x: null };
  const palette: Record<string, string> = {};
  for (const s of SLOT_KEYS) {
    if (!t.slots[s]) continue;
    const id = opts.ramps?.[s] ?? base[s];
    const r = id ? ramp(id) : null;
    if (!r) return { ok: false, error: `unknown ${s} ramp ${String(id)}` };
    if (!t.slots[s]!.includes(r.family)) return { ok: false, error: `ramp ${r.id} is a ${r.family} ramp; slot ${s} of ${t.id} takes ${t.slots[s]!.join("/")}` };
    chosen[s] = r.id;
    r.shades.forEach((hex, i) => { palette[`${s}${i + 1}`] = hex.toLowerCase(); });
  }
  for (const [ch, hex] of Object.entries(t.fixed ?? {})) palette[`f${ch}`] = hex.toLowerCase();
  const keyOf = (ch: string): string | null => {
    if (ch === ".") return null;
    for (const s of SLOT_KEYS) { const i = SLOT_CHARS[s].indexOf(ch); if (i >= 0) return `${s}${i + 1}`; }
    return `f${ch}`;
  };
  const ops: Op[] = gridOps(t.grid, keyOf);
  const grit = t.profile === "tile" ? noiseAmount(dna.noise) : 0; // grain only ever on tiles (see taxonomy noiseLevels)
  if (grit > 0) ops.push({ op: "noise", amount: grit, seed: 7 });
  if (t.outline && dna.outline !== "none") {
    palette.ol = dna.outline === "black" ? "#0e0d12" : darkenTo(palette.m1 ?? palette.x1 ?? palette.h1 ?? "#202020");
    ops.push({ op: "outline", c: "ol" });
  }
  // drop palette entries the grid never uses (keeps the spec small and the palette honest)
  const usedKeys = new Set(ops.flatMap((o) => ("c" in o ? [o.c] : [])));
  for (const k of Object.keys(palette)) if (!usedKeys.has(k)) delete palette[k];
  if (ops.length > MAX_OPS) return { ok: false, error: `${t.id} compiles to ${ops.length} ops (max ${MAX_OPS})` };
  const name = opts.name ?? variantName(t, Object.fromEntries(SLOT_KEYS.filter((s) => chosen[s]).map((s) => [s, chosen[s]!])) as TemplateVariant);
  const c = checkSpec({ name, size: t.size, palette, ops });
  if (!c.ok) return { ok: false, error: c.error };
  return { ok: true, spec: c.spec, ramps: chosen, dna: dna.id };
}

