  version: number;
  categories: { id: string; label: string; subcategories: { id: string; label: string; keywords: string[]; uvNotes?: string }[] }[];
  useCases: { id: string; label: string; broader: string[] }[];
  styleDna: { lightDirections: string[]; outlineRules: { id: OutlineRule; label: string; note: string }[]; noiseLevels: { id: string; amount: number; note: string }[]; presets: DnaPreset[]; ramps: Ramp[] };
  ledger: { fields: string[]; builtinProvenance: string; builtinLicence: string; builtinLicenceStatus: string; originalRule: string };
  synonyms: Record<string, string>;
  querySynonyms: Record<string, string[]>;
  stopWords: string[];
