#!/usr/bin/env python3
"""Authoring aid for the Cyrus texture library's TILE templates (block faces, skin swatches).

Deterministic, dependency-free. Prints a TypeScript module (lib/cyrus/texture-library/templates-tiles.ts) whose grids
are ORIGINAL art produced here from simple rules (toroidal cells, boards, rings, slats): nothing is copied or traced
from Minecraft or any other game. The grids are the committed source of truth; re-run only to regenerate on purpose:
  python3 scripts/cyrus/texture-tile-grids.py > lib/cyrus/texture-library/templates-tiles.ts
Legend as in lib/cyrus/texture-library/compile.ts: '1'-'5' ramp m, 'a'-'e' ramp h, 'p'-'t' ramp x, '.' clear.
"""
import math, random, json

N = 16
M = "12345"; H = "abcde"; X = "pqrst"


def grid(fill="."):
    return [[fill] * N for _ in range(N)]


def rows(g):
    return ["".join(r) for r in g]


def tdist(ax, ay, bx, by):
    dx = abs(ax - bx); dy = abs(ay - by)
    dx = min(dx, N - dx); dy = min(dy, N - dy)
    return math.hypot(dx, dy)


def cells(seeds):
    """nearest + second nearest seed per pixel on the torus."""
    out = {}
    for y in range(N):
        for x in range(N):
            ds = sorted((tdist(x + .5, y + .5, sx, sy), i) for i, (sx, sy) in enumerate(seeds))
            out[(x, y)] = (ds[0][1], ds[1][0] - ds[0][0])
    return out


def cobble(seed, nseeds=7, gap=1.05, ramp=M):
    r = random.Random(seed)
    # jittered grid seeds so stones are evenly sized
    seeds = []
    k = int(math.ceil(math.sqrt(nseeds)))
    for i in range(nseeds):
        gx, gy = i % k, i // k
        seeds.append(((gx + .5 + r.uniform(-.3, .3)) * N / k, (gy + .5 + r.uniform(-.3, .3)) * N / math.ceil(nseeds / k)))
    c = cells(seeds)
    g = grid()
    for (x, y), (ci, edge) in c.items():
        if edge < gap:
            g[y][x] = ramp[0]; continue
        up = c[(x, (y - 1) % N)]; lf = c[((x - 1) % N, y)]; dn = c[(x, (y + 1) % N)]; rt = c[((x + 1) % N, y)]
        top_edge = up[0] != ci or up[1] < gap or lf[0] != ci or lf[1] < gap
        bot_edge = dn[0] != ci or dn[1] < gap or rt[0] != ci or rt[1] < gap
        v = 2
        if top_edge: v = 3
        if bot_edge: v = 1
        if top_edge and not bot_edge and (up[0] != ci or up[1] < gap) and (lf[0] != ci or lf[1] < gap): v = 4
        g[y][x] = ramp[v]
    # a few deliberate chips on the darker side of each stone
    for _ in range(5):
        x, y = r.randrange(N), r.randrange(N)
        if g[y][x] == ramp[2]: g[y][x] = ramp[1]
    return g


def polished(ramp=M):
    g = grid(ramp[2])
    for i in range(N):
        g[0][i] = ramp[3]; g[i][0] = ramp[3]
        g[N - 1][i] = ramp[1]; g[i][N - 1] = ramp[1]
    g[0][0] = ramp[4]; g[1][1] = ramp[3]
    g[N - 1][0] = ramp[2]; g[0][N - 1] = ramp[2]
    for (x, y) in [(4, 5), (5, 5), (10, 9), (11, 10), (6, 12), (12, 3)]:
        g[y][x] = ramp[1]
    for (x, y) in [(3, 4), (9, 8), (5, 11), (11, 2)]:
        g[y][x] = ramp[3]
    return g


def bricks(ramp=M, mortar="b", w=8, h=4, light_mortar=False):
    g = grid()
    for y in range(N):
        row = y // h; off = (w // 2) * (row % 2)
        for x in range(N):
            bx = (x + off) % w; by = y % h
            if by == h - 1 or bx == w - 1:
                g[y][x] = mortar; continue
            v = 2
            if by == 0: v = 3
            if bx == 0: v = 3
            if by == h - 2: v = 1
            if by == 0 and bx == 0: v = 4
            g[y][x] = ramp[v]
    # weathering: a darker chip per few bricks
    for (x, y) in [(3, 1), (12, 5), (6, 9), (14, 13), (9, 2)]:
        if g[y][x] in ramp[2:]: g[y][x] = ramp[1]
    return g


def flagstone(ramp=M, mortar="1"):
    g = grid()
    for y in range(N):
        for x in range(N):
            bx, by = x % 8, y % 8
            if bx == 7 or by == 7:
                g[y][x] = ramp[0]; continue
            v = 2
            if bx == 0 or by == 0: v = 3
            if bx == 6 or by == 6: v = 1
            if bx == 0 and by == 0: v = 4
            g[y][x] = ramp[v]
    for (x, y) in [(3, 3), (11, 2), (2, 11), (12, 12), (4, 10)]:
        g[y][x] = ramp[3]
    for (x, y) in [(4, 4), (12, 3), (3, 12), (13, 13), (10, 5)]:
        g[y][x] = ramp[1]
    return g


def ore(seed, ramp_ore=M, ramp_rock=H):
    g = cobble(seed, nseeds=6, gap=0.9, ramp=ramp_rock)
    # soften the rock: no stone highlights so the ore reads first
    for y in range(N):
        for x in range(N):
            if g[y][x] == ramp_rock[4]: g[y][x] = ramp_rock[3]
    r = random.Random(seed * 7 + 1)
    shapes = [[(0, 0), (1, 0), (0, 1), (1, 1), (2, 1)], [(0, 0), (1, 0), (1, 1), (2, 1)], [(1, 0), (0, 1), (1, 1), (2, 1), (1, 2)], [(0, 0), (1, 0), (1, 1)]]
    centres = [(2, 2), (9, 1), (12, 7), (4, 9), (10, 12), (1, 13)]
    for i, (cx, cy) in enumerate(centres):
        sh = shapes[(i + seed) % len(shapes)]
        pts = [((cx + dx) % N, (cy + dy) % N) for dx, dy in sh]
        for (x, y) in pts: g[y][x] = ramp_ore[2]
        # light top-left pixel, dark bottom-right rim
        x0, y0 = min(pts, key=lambda p: (p[1], p[0]))
        g[y0][x0] = ramp_ore[4]
        x1, y1 = max(pts, key=lambda p: (p[1], p[0]))
        g[y1][x1] = ramp_ore[1]
        for (x, y) in pts:
            for (dx, dy) in [(1, 0), (0, 1)]:
                nx, ny = (x + dx) % N, (y + dy) % N
                if (nx, ny) not in pts and g[ny][nx] in ramp_rock: g[ny][nx] = ramp_rock[0]
        if len(pts) >= 4:
            x2, y2 = pts[1]; g[y2][x2] = ramp_ore[3]
    return g


def planks(ramp=M, seed=3):
    r = random.Random(seed)
    g = grid()
    joints = [3, 11, 6, 14]
    for y in range(N):
        b = y // 4; by = y % 4
        for x in range(N):
            if by == 3:
                g[y][x] = ramp[0]; continue
            if x == joints[b]:
                g[y][x] = ramp[0]; continue
            v = 2
            if by == 0: v = 3
            if x == (joints[b] + 1) % N and by < 3: v = 3
            g[y][x] = ramp[v]
        # grain streaks
    for b in range(4):
        for k in range(2):
            y = b * 4 + 1 + k
            x0 = r.randrange(N); ln = r.randint(3, 6)
            for i in range(ln):
                x = (x0 + i) % N
                if g[y][x] == ramp[2]: g[y][x] = ramp[1] if k else ramp[3]
    return g


def bark(ramp=M, seed=5):
    r = random.Random(seed)
    g = grid()
    ridge = [r.choice([0, 1]) for _ in range(N)]
    for x in range(N):
        col = x % 4
        for y in range(N):
            wob = 1 if ((y + x * 3) % 7) in (0, 1) else 0
            c = (col + wob) % 4
            g[y][x] = ramp[[3, 2, 1, 0][c]]
    for _ in range(6):
        x, y = r.randrange(N), r.randrange(N)
        g[y][x] = ramp[4] if g[y][x] == ramp[3] else g[y][x]
    return g


def log_top(ramp_wood=M, ramp_bark=H):
    g = grid()
    cx = cy = 7.5
    for y in range(N):
        for x in range(N):
            if x in (0, N - 1) or y in (0, N - 1):
                g[y][x] = ramp_bark[1] if (x + y) % 3 else ramp_bark[0]; continue
            if x in (1, N - 2) or y in (1, N - 2):
                g[y][x] = ramp_bark[2]; continue
            d = math.hypot(x + .5 - 8, y + .5 - 8)
            ring = int(d * 1.15) % 3
            g[y][x] = ramp_wood[[3, 2, 1][ring]] if d > 1.2 else ramp_wood[1]
            if ring == 0 and x < 8 and y < 8: g[y][x] = ramp_wood[4] if d > 1.2 else g[y][x]
    return g


def leaves(seed=11, ramp=M):
    r = random.Random(seed)
    g = grid()
    for y in range(N):
        for x in range(N):
            g[y][x] = ramp[2]
    # leaf clusters: highlight top-left, shadow bottom-right
    for (cx, cy) in [(2, 2), (8, 1), (13, 4), (5, 7), (11, 10), (1, 11), (7, 13), (14, 14)]:
        for dy in range(-1, 2):
            for dx in range(-1, 2):
                x, y = (cx + dx) % N, (cy + dy) % N
                g[y][x] = ramp[3] if dx + dy < 0 else ramp[2] if dx + dy == 0 else ramp[1]
        g[(cy - 1) % N][(cx - 1) % N] = ramp[4]
    # holes (clear) between clusters
    for (x, y) in [(5, 3), (10, 5), (2, 8), (14, 9), (8, 9), (4, 14), (11, 14), (15, 1), (12, 1)]:
        g[y][x] = "."
    for _ in range(8):
        x, y = r.randrange(N), r.randrange(N)
        if g[y][x] == ramp[2]: g[y][x] = ramp[0]
    return g


def moss(seed=13, ramp=M):
    r = random.Random(seed)
    g = grid(ramp[2])
    for _ in range(26):
        x, y = r.randrange(N), r.randrange(N)
        g[y][x] = ramp[3]; g[(y + 1) % N][x] = ramp[1]
    for _ in range(10):
        x, y = r.randrange(N), r.randrange(N)
        g[y][x] = ramp[4]
    return g


def glass(ramp=M):
    g = grid()
    for i in range(N):
        g[0][i] = ramp[3]; g[i][0] = ramp[3]; g[N - 1][i] = ramp[1]; g[i][N - 1] = ramp[1]
    g[0][0] = ramp[4]
    for i in range(3, 8):
        g[i][i - 1] = ramp[4]; g[i][i] = ramp[3]
    for i in range(9, 12):
        g[i - 6][i] = ramp[3]
    g[12][11] = ramp[3]; g[11][12] = ramp[2]
    return g


def metal_plate(ramp=M):
    g = grid(ramp[2])
    for i in range(N):
        g[0][i] = ramp[4]; g[i][0] = ramp[4]; g[N - 1][i] = ramp[0]; g[i][N - 1] = ramp[0]
        g[1][i] = ramp[3] if 0 < i < N - 1 else g[1][i]; g[i][1] = ramp[3] if 0 < i < N - 1 else g[i][1]
        g[N - 2][i] = ramp[1] if 0 < i < N - 1 else g[N - 2][i]; g[i][N - 2] = ramp[1] if 0 < i < N - 1 else g[i][N - 2]
    for (x, y) in [(3, 3), (12, 3), (3, 12), (12, 12)]:
        g[y][x] = ramp[4]; g[y][x + 1] = ramp[1]; g[y + 1][x] = ramp[1]; g[y + 1][x + 1] = ramp[0]
    for (x, y) in [(6, 7), (7, 7), (8, 8), (9, 8)]:
        g[y][x] = ramp[3]
    return g


def tech_panel(ramp=M, glow=X):
    g = metal_plate(ramp)
    for x in range(4, 12):
        g[7][x] = ramp[0]; g[8][x] = glow[3] if x % 3 else glow[4]; g[9][x] = ramp[3]
    for (x, y) in [(4, 4), (6, 4)]:
        g[y][x] = glow[4]; g[y][x + 1] = glow[2]
    g[4][10] = glow[1]; g[4][11] = glow[1]
    for y in range(11, 13):
        for x in (5, 7, 9):
            g[y][x] = ramp[0]
    return g


def vent(ramp=M):
    g = grid(ramp[2])
    for i in range(N):
        g[0][i] = ramp[3]; g[i][0] = ramp[3]; g[N - 1][i] = ramp[0]; g[i][N - 1] = ramp[0]
    for y in range(2, 14, 3):
        for x in range(2, 14):
            g[y][x] = ramp[0]; g[y + 1][x] = ramp[4] if x == 2 else ramp[3]
    return g


def circuit(ramp=M, trace=X):
    g = grid(ramp[1])
    for (x, y) in [(x, y) for y in range(N) for x in range(N) if (x * 7 + y * 3) % 11 == 0]:
        g[y][x] = ramp[0]
    paths = [[(0, 3), (5, 3), (5, 8), (10, 8), (10, 3), (15, 3)], [(2, 15), (2, 11), (8, 11), (8, 15)], [(13, 0), (13, 6), (15, 6)], [(0, 6), (2, 6), (2, 8)]]
    for p in paths:
        for (ax, ay), (bx, by) in zip(p, p[1:]):
            for t in range(max(abs(bx - ax), abs(by - ay)) + 1):
                x = ax + (t if bx > ax else -t if bx < ax else 0); y = ay + (t if by > ay else -t if by < ay else 0)
                g[y % N][x % N] = trace[2]
    for (x, y) in [(5, 3), (10, 8), (2, 11), (8, 11), (13, 6), (2, 8)]:
        g[y][x] = trace[4]
    for (x, y) in [(12, 11), (13, 11), (12, 12), (13, 12)]:
        g[y][x] = ramp[3]
    g[11][12] = ramp[4]; g[13][12] = ramp[0]; g[13][13] = ramp[0]
    return g


def rune_tile(ramp=M, glow=X):
    g = polished(ramp)
    rune = [(7, 3), (8, 3), (7, 4), (6, 5), (9, 5), (5, 6), (10, 6), (7, 6), (8, 6), (7, 7), (8, 7), (7, 8), (8, 8), (5, 9), (10, 9), (6, 10), (9, 10), (7, 11), (8, 11), (7, 12)]
    for (x, y) in rune:
        g[y][x] = glow[3]
    for (x, y) in [(7, 3), (5, 6), (7, 6), (5, 9)]:
        g[y][x] = glow[4]
    for (x, y) in rune:
        nx, ny = x + 1, y + 1
        if (nx, ny) not in rune and g[ny][nx] in M: g[ny][nx] = ramp[0]
    return g


def mosaic(a=M, b=H):
    g = grid()
    for y in range(N):
        for x in range(N):
            tx, ty = x // 4, y // 4
            rr = a if (tx + ty) % 2 == 0 else b
            bx, by = x % 4, y % 4
            v = 2
            if bx == 0 or by == 0: v = 3
            if bx == 3 or by == 3: v = 1
            if bx == 0 and by == 0: v = 4
            g[y][x] = rr[v]
    return g


def fur(seed=17, ramp=M):
    r = random.Random(seed)
    g = grid(ramp[2])
    for k in range(34):
        x, y = r.randrange(N), r.randrange(N)
        ln = r.randint(2, 3)
        for i in range(ln):
            g[(y + i) % N][(x + i // 2) % N] = ramp[3] if i == 0 else ramp[1]
    for _ in range(8):
        x, y = r.randrange(N), r.randrange(N)
        g[y][x] = ramp[4]
    return g


def scales(ramp=M):
    g = grid()
    for y in range(N):
        for x in range(N):
            row = y // 4; off = 2 * (row % 2)
            bx = (x + off) % 4; by = y % 4
            # each scale: a 4x4 rounded plate, light top-left
            v = [[3, 4, 3, 2], [3, 3, 2, 1], [2, 2, 2, 1], [1, 1, 1, 0]][by][bx]
            g[y][x] = ramp[v]
    return g


def feathers(ramp=M):
    g = grid()
    for y in range(N):
        for x in range(N):
            row = y // 8; off = 4 * (row % 2)
            bx = (x + off) % 8; by = y % 8
            # a vane: shaft down the middle, barbs angled out
            if bx == 4: v = 4 if by < 5 else 3
            elif by >= 7: v = 0
            else:
                d = abs(bx - 4)
                v = 3 if bx < 4 else 2
                if by + d >= 8: v = 1
                if (by + d) % 3 == 0: v = max(v - 1, 0)
            g[y][x] = ramp[v]
    return g


def T(id, name, sub, cat, g, slots, variants, use, tags, tileable=True, note=None, fixed=None):
    return {"id": id, "name": name, "category": cat, "sub": sub, "useCases": use, "tags": tags, "size": 16, "profile": "tile", "tileable": tileable,
            "outline": False, "slots": slots, "variants": variants, "grid": rows(g), **({"fixed": fixed} if fixed else {}), **({"note": note} if note else {})}


STONE = ["stone"]
out = [
    T("cobble", "Rubble stone", "stone", "blocks", cobble(4), {"m": STONE}, [{"m": "stone"}, {"m": "slate"}, {"m": "sandstone"}, {"m": "basalt"}], ["building_block"], ["stone", "cobble", "rubble", "rock", "block"]),
    T("polished_stone", "Polished stone", "stone", "blocks", polished(), {"m": STONE}, [{"m": "stone"}, {"m": "slate"}, {"m": "sandstone"}, {"m": "basalt"}], ["building_block"], ["stone", "polished", "smooth", "slab", "block"],
      note="bevelled on purpose: repeats as a grid of slabs"),
    T("bricks", "Bricks", "stone", "blocks", bricks(mortar="c"), {"m": STONE, "h": STONE}, [{"m": "clay", "h": "stone"}, {"m": "stone", "h": "basalt"}, {"m": "sandstone", "h": "sandstone"}, {"m": "slate", "h": "basalt"}], ["building_block"], ["brick", "bricks", "wall", "masonry", "block"]),
    T("flagstone", "Flagstone tiles", "decorative", "blocks", flagstone(), {"m": STONE}, [{"m": "stone"}, {"m": "sandstone"}, {"m": "slate"}], ["building_block"], ["tile", "tiles", "floor", "flagstone", "stone", "block"]),
    T("ore", "Ore vein", "ore", "blocks", ore(2), {"m": ["metal", "gem"], "h": STONE}, [{"m": "iron", "h": "stone"}, {"m": "gold", "h": "stone"}, {"m": "copper", "h": "stone"}, {"m": "crystal", "h": "stone"}, {"m": "ruby", "h": "stone"}, {"m": "emerald", "h": "stone"}, {"m": "amethyst", "h": "slate"}, {"m": "voidsteel", "h": "basalt"}], ["ore_block"], ["ore", "vein", "mineral", "mining", "block"]),
    T("planks", "Planks", "wood", "blocks", planks(), {"m": ["wood"]}, [{"m": "oak"}, {"m": "walnut"}, {"m": "birch"}, {"m": "crimson"}], ["building_block"], ["plank", "planks", "wood", "floor", "block"]),
    T("bark", "Log bark", "wood", "blocks", bark(), {"m": ["wood"]}, [{"m": "oak"}, {"m": "walnut"}, {"m": "birch"}, {"m": "crimson"}], ["building_block"], ["log", "bark", "wood", "tree", "block"]),
    T("log_top", "Log end", "wood", "blocks", log_top(), {"m": ["wood"], "h": ["wood"]}, [{"m": "oak", "h": "walnut"}, {"m": "birch", "h": "oak"}, {"m": "crimson", "h": "walnut"}], ["building_block"], ["log", "rings", "stump", "wood", "block"], tileable=False),
    T("leaves", "Leaves", "plant", "blocks", leaves(), {"m": ["plant"]}, [{"m": "moss"}, {"m": "autumn"}], ["building_block"], ["leaf", "leaves", "foliage", "tree", "plant", "block"]),
    T("moss", "Moss", "plant", "blocks", moss(), {"m": ["plant"]}, [{"m": "moss"}, {"m": "autumn"}], ["building_block"], ["moss", "grass", "turf", "plant", "block"]),
    T("glass", "Glass", "glass", "blocks", glass(), {"m": ["glass"]}, [{"m": "glass"}, {"m": "tint_rose"}], ["building_block"], ["glass", "window", "pane", "block"]),
    T("metal_plate", "Riveted plate", "metal", "blocks", metal_plate(), {"m": ["metal"]}, [{"m": "iron"}, {"m": "copper"}, {"m": "gold"}, {"m": "voidsteel"}], ["building_block", "machine_block"], ["metal", "plate", "rivet", "steel", "block"]),
    T("tech_panel", "Tech panel", "metal", "blocks", tech_panel(), {"m": ["metal"], "x": ["tech", "gem", "effect"]}, [{"m": "iron", "x": "tech_teal"}, {"m": "voidsteel", "x": "arcane"}, {"m": "iron", "x": "signal_amber"}], ["machine_block"], ["tech", "panel", "machine", "light", "block"]),
    T("vent", "Vent grate", "metal", "blocks", vent(), {"m": ["metal"]}, [{"m": "iron"}, {"m": "copper"}, {"m": "voidsteel"}], ["machine_block"], ["vent", "grate", "grille", "metal", "tech", "block"]),
    T("circuit", "Circuit board", "metal", "blocks", circuit(), {"m": ["tech", "stone"], "x": ["metal", "tech"]}, [{"m": "tech_teal", "x": "gold"}, {"m": "slate", "x": "signal_amber"}], ["machine_block"], ["circuit", "board", "tech", "electronic", "block"]),
    T("rune_tile", "Rune tile", "decorative", "blocks", rune_tile(), {"m": STONE, "x": ["effect", "gem"]}, [{"m": "slate", "x": "arcane"}, {"m": "basalt", "x": "flame"}, {"m": "sandstone", "x": "azure"}], ["building_block", "magic_item"], ["rune", "glyph", "carved", "magic", "decorative", "block"], tileable=False),
    T("mosaic", "Mosaic", "decorative", "blocks", mosaic(), {"m": STONE, "h": STONE}, [{"m": "sandstone", "h": "clay"}, {"m": "stone", "h": "slate"}], ["building_block"], ["mosaic", "checker", "tiles", "pattern", "decorative", "block"]),
    T("fur", "Fur swatch", "quadruped", "entity_skins", fur(), {"m": ["cloth"]}, [{"m": "fur_brown"}, {"m": "fur_grey"}, {"m": "ash"}], ["mob_skin"], ["fur", "hide", "pelt", "beast", "skin", "swatch"]),
    T("scales", "Scale swatch", "quadruped", "entity_skins", scales(), {"m": ["cloth", "metal", "gem"]}, [{"m": "scale_green"}, {"m": "voidsteel"}, {"m": "ruby"}], ["mob_skin"], ["scales", "scale", "reptile", "dragon", "skin", "swatch"]),
    T("feathers", "Feather swatch", "flyer", "entity_skins", feathers(), {"m": ["cloth"]}, [{"m": "ash"}, {"m": "fur_brown"}, {"m": "fur_grey"}], ["mob_skin"], ["feather", "feathers", "wing", "bird", "skin", "swatch"]),
]
print("// GENERATED by scripts/cyrus/texture-tile-grids.py (original tile art from simple deterministic rules; see that file).")
print("// The grids are the committed source; regenerate only on purpose. Do not hand-edit.")
