#!/usr/bin/env python3
"""Authoring aid for the Cyrus texture library's TILE templates (block faces, skin swatches).

Deterministic, dependency-free. Prints a TypeScript module (lib/cyrus/texture-library/templates-tiles.ts) whose grids
are ORIGINAL art produced here from simple rules (toroidal cells, boards, rings, slats): nothing is copied or traced
from Minecraft or any other game. The grids are the committed source of truth; re-run only to regenerate on purpose:
  python3 scripts/cyrus/texture-tile-grids.py > lib/cyrus/texture-library/templates-tiles.ts
Legend as in lib/cyrus/texture-library/compile.ts: '1'-'5' ramp m, 'a'-'e' ramp h, 'p'-'t' ramp x, '.' clear.
"""
import math, random, json

N = 16
M = "12345"; H = "abcde"; X = "pqrst"


def grid(fill="."):
    return [[fill] * N for _ in range(N)]


def rows(g):
    return ["".join(r) for r in g]


def tdist(ax, ay, bx, by):
    dx = abs(ax - bx); dy = abs(ay - by)
    dx = min(dx, N - dx); dy = min(dy, N - dy)
    return math.hypot(dx, dy)


def cells(seeds):
    """nearest + second nearest seed per pixel on the torus."""
    out = {}
    for y in range(N):
        for x in range(N):
            ds = sorted((tdist(x + .5, y + .5, sx, sy), i) for i, (sx, sy) in enumerate(seeds))
            out[(x, y)] = (ds[0][1], ds[1][0] - ds[0][0])
    return out


def cobble(seed, nseeds=7, gap=1.05, ramp=M):
    r = random.Random(seed)
    # jittered grid seeds so stones are evenly sized
    seeds = []
    k = int(math.ceil(math.sqrt(nseeds)))
    for i in range(nseeds):
        gx, gy = i % k, i // k
        seeds.append(((gx + .5 + r.uniform(-.3, .3)) * N / k, (gy + .5 + r.uniform(-.3, .3)) * N / math.ceil(nseeds / k)))
    c = cells(seeds)
    g = grid()
    for (x, y), (ci, edge) in c.items():
        if edge < gap:
            g[y][x] = ramp[0]; continue
        up = c[(x, (y - 1) % N)]; lf = c[((x - 1) % N, y)]; dn = c[(x, (y + 1) % N)]; rt = c[((x + 1) % N, y)]
        top_edge = up[0] != ci or up[1] < gap or lf[0] != ci or lf[1] < gap
        bot_edge = dn[0] != ci or dn[1] < gap or rt[0] != ci or rt[1] < gap
        v = 2
        if top_edge: v = 3
        if bot_edge: v = 1
        if top_edge and not bot_edge and (up[0] != ci or up[1] < gap) and (lf[0] != ci or lf[1] < gap): v = 4
        g[y][x] = ramp[v]
    # a few deliberate chips on the darker side of each stone
    for _ in range(5):
        x, y = r.randrange(N), r.randrange(N)
        if g[y][x] == ramp[2]: g[y][x] = ramp[1]
    return g


def polished(ramp=M):
    g = grid(ramp[2])
    for i in range(N):
        g[0][i] = ramp[3]; g[i][0] = ramp[3]
        g[N - 1][i] = ramp[1]; g[i][N - 1] = ramp[1]
    g[0][0] = ramp[4]; g[1][1] = ramp[3]
    g[N - 1][0] = ramp[2]; g[0][N - 1] = ramp[2]
    for (x, y) in [(4, 5), (5, 5), (10, 9), (11, 10), (6, 12), (12, 3)]:
        g[y][x] = ramp[1]
    for (x, y) in [(3, 4), (9, 8), (5, 11), (11, 2)]:
        g[y][x] = ramp[3]
    return g


def bricks(ramp=M, mortar="b", w=8, h=4, light_mortar=False):
    g = grid()
    for y in range(N):
        row = y // h; off = (w // 2) * (row % 2)
        for x in range(N):
            bx = (x + off) % w; by = y % h
            if by == h - 1 or bx == w - 1:
                g[y][x] = mortar; continue
            v = 2
            if by == 0: v = 3
            if bx == 0: v = 3
            if by == h - 2: v = 1
            if by == 0 and bx == 0: v = 4
            g[y][x] = ramp[v]
    # weathering: a darker chip per few bricks
    for (x, y) in [(3, 1), (12, 5), (6, 9), (14, 13), (9, 2)]:
        if g[y][x] in ramp[2:]: g[y][x] = ramp[1]
    return g


def flagstone(ramp=M, mortar="1"):
    g = grid()
    for y in range(N):
        for x in range(N):
            bx, by = x % 8, y % 8
            if bx == 7 or by == 7:
                g[y][x] = ramp[0]; continue
            v = 2
