def ore(seed, ramp_ore=M, ramp_rock=H):
    g = cobble(seed, nseeds=6, gap=0.9, ramp=ramp_rock)
    # soften the rock: no stone highlights so the ore reads first
    for y in range(N):
        for x in range(N):
            if g[y][x] == ramp_rock[4]: g[y][x] = ramp_rock[3]
    r = random.Random(seed * 7 + 1)
    shapes = [[(0, 0), (1, 0), (0, 1), (1, 1), (2, 1)], [(0, 0), (1, 0), (1, 1), (2, 1)], [(1, 0), (0, 1), (1, 1), (2, 1), (1, 2)], [(0, 0), (1, 0), (1, 1)]]
    centres = [(2, 2), (9, 1), (12, 7), (4, 9), (10, 12), (1, 13)]
    for i, (cx, cy) in enumerate(centres):
        sh = shapes[(i + seed) % len(shapes)]
        pts = [((cx + dx) % N, (cy + dy) % N) for dx, dy in sh]
        for (x, y) in pts: g[y][x] = ramp_ore[2]
        # light top-left pixel, dark bottom-right rim
        x0, y0 = min(pts, key=lambda p: (p[1], p[0]))
        g[y0][x0] = ramp_ore[4]
        x1, y1 = max(pts, key=lambda p: (p[1], p[0]))
        g[y1][x1] = ramp_ore[1]
        for (x, y) in pts:
            for (dx, dy) in [(1, 0), (0, 1)]:
                nx, ny = (x + dx) % N, (y + dy) % N
                if (nx, ny) not in pts and g[ny][nx] in ramp_rock: g[ny][nx] = ramp_rock[0]
