            x2, y2 = pts[1]; g[y2][x2] = ramp_ore[3]
    return g


def planks(ramp=M, seed=3):
    r = random.Random(seed)
    g = grid()
    joints = [3, 11, 6, 14]
    for y in range(N):
        b = y // 4; by = y % 4
        for x in range(N):
            if by == 3:
                g[y][x] = ramp[0]; continue
            if x == joints[b]:
                g[y][x] = ramp[0]; continue
            v = 2
            if by == 0: v = 3
            if x == (joints[b] + 1) % N and by < 3: v = 3
            g[y][x] = ramp[v]
