    for b in range(4):
        for k in range(2):
            y = b * 4 + 1 + k
            x0 = r.randrange(N); ln = r.randint(3, 6)
            for i in range(ln):
                x = (x0 + i) % N
                if g[y][x] == ramp[2]: g[y][x] = ramp[1] if k else ramp[3]
    return g


def bark(ramp=M, seed=5):
    r = random.Random(seed)
    g = grid()
    ridge = [r.choice([0, 1]) for _ in range(N)]
    for x in range(N):
        col = x % 4
        for y in range(N):
            wob = 1 if ((y + x * 3) % 7) in (0, 1) else 0
            c = (col + wob) % 4
            g[y][x] = ramp[[3, 2, 1, 0][c]]
    for _ in range(6):
        x, y = r.randrange(N), r.randrange(N)
        g[y][x] = ramp[4] if g[y][x] == ramp[3] else g[y][x]
    return g


def log_top(ramp_wood=M, ramp_bark=H):
    g = grid()
    cx = cy = 7.5
    for y in range(N):
        for x in range(N):
            if x in (0, N - 1) or y in (0, N - 1):
                g[y][x] = ramp_bark[1] if (x + y) % 3 else ramp_bark[0]; continue
            if x in (1, N - 2) or y in (1, N - 2):
                g[y][x] = ramp_bark[2]; continue
            d = math.hypot(x + .5 - 8, y + .5 - 8)
            ring = int(d * 1.15) % 3
            g[y][x] = ramp_wood[[3, 2, 1][ring]] if d > 1.2 else ramp_wood[1]
            if ring == 0 and x < 8 and y < 8: g[y][x] = ramp_wood[4] if d > 1.2 else g[y][x]
    return g


