export const isNearCopy = (s: Similarity) => s.maskIoU >= 0.9 && s.lumCorr >= 0.9;
/** Same drawing AND nearly the same colours: two library variants a viewer could not tell apart. */
export const isColourLookalike = (s: Similarity) => isNearCopy(s) && s.colourDist < 28;

export type NearCopyResult = { status: "pass" | "fail" | "not_run"; matched: number | null; best: Similarity | null; message: string };

export function checkNearCopy(img: Raster, refs: readonly Fingerprint[]): NearCopyResult {
  if (!refs.length) return { status: "not_run", matched: null, best: null, message: "no vanilla reference fingerprints on this host; compute them on the build host from the server jar (never commit them)" };
  const fp = fingerprint(img);
  let best: Similarity | null = null, at = -1;
  refs.forEach((r, i) => { const s = similarity(fp, r); if (!best || s.maskIoU + s.lumCorr > best.maskIoU + best.lumCorr) { best = s; at = i; } });
  const hit = best !== null && isNearCopy(best);
  return { status: hit ? "fail" : "pass", matched: hit ? at : null, best, message: hit ? "too close to a reference texture (shape and shading match); draw it from scratch" : "no reference texture matches" };
}
