cd /tank/dev-worktrees/cyrus-r1 && cat > lib/cyrus/texture-library/build.ts <<'EOF'
// Builds the texture library manifest from the templates (deterministic; SERVER/SCRIPT side because it hashes with
// node:crypto). scripts/cyrus/texture-library-manifest.ts writes the result to ./library.manifest.json and
// test/cyrus-texture-library.test.ts re-derives every entry and compares (same spec, same PNG hash).
import { canonicalJson, sha256Hex } from "../assets/textures";
import { encodePng } from "../textures/png";
import { render } from "../textures/render";
import { textureQuality } from "../textures/quality";
import { DEFAULT_DNA, instantiate, ramp, TEXTURE_TAXONOMY, type TextureTemplate } from "./compile";
import { TEMPLATES } from "./templates";
import type { TextureLibraryItem, TextureManifest } from "./library";

export const TEXTURE_LIBRARY_VERSION = 1;
export const LIBRARY_DATE = "2026-10-10";

const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

export function buildItem(t: TextureTemplate, v: TextureTemplate["variants"][number]): TextureLibraryItem {
  const inst = instantiate(t, { ramps: v, dna: DEFAULT_DNA });
  if (!inst.ok) throw new Error(`${t.id}: ${inst.error}`);
  const raster = render(inst.spec);
  const q = textureQuality(raster, { profile: t.profile, tileable: t.tileable });
  const png = encodePng(raster);
  const primary = v.m ?? v.x ?? v.h ?? null;
  const pr = primary ? ramp(primary) : null;
  const L = TEXTURE_TAXONOMY.ledger;
  const palette = q.checks.find((c) => c.id === "palette_size")?.value ?? 0;
  const coverage = q.checks.find((c) => c.id === "transparency")?.value ?? 0;
  const rampTags = Object.values(v).flatMap((id) => { const r = ramp(id!); return r ? [r.id, ...r.label.toLowerCase().split(/[^a-z0-9]+/), r.family] : []; });
  return {
    id: inst.spec.name,
    templateId: t.id,
    name: pr ? `${cap(pr.label)} ${t.name.toLowerCase()}` : t.name,
    category: t.category,
    sub: t.sub,
    useCases: [...t.useCases],
    tags: [...new Set([...t.tags, ...rampTags].filter((w) => w.length > 1))],
    ramps: inst.ramps,
    dna: inst.dna,
    descriptors: { size: t.size, paletteSize: palette as number, transparency: coverage === 1 ? "opaque" : "cutout", tileable: t.tileable, style: inst.dna, material: pr?.id ?? null },
    spec: inst.spec,
    specSha256: sha256Hex(canonicalJson(inst.spec)),
    pngSha256: sha256Hex(png),
    quality: { version: q.version, verdict: q.verdict, profile: t.profile, checks: Object.fromEntries(q.checks.map((c) => [c.id, c.status])) },
    ledger: { provenance: L.builtinProvenance, licence: L.builtinLicence, licenceStatus: L.builtinLicenceStatus, author: "Cyrus (Nxeon)", original: true, createdAt: LIBRARY_DATE, derivedFrom: `template:${t.id}` },
    ...(t.note ? { note: t.note } : {}),
  };
}

export function buildManifest(): TextureManifest {
  const items = TEMPLATES.flatMap((t) => t.variants.map((v) => buildItem(t, v)));
  return { version: TEXTURE_LIBRARY_VERSION, generatedAt: LIBRARY_DATE, taxonomyVersion: TEXTURE_TAXONOMY.version, templateCount: TEMPLATES.length, items };
}
