// Contact sheets for the texture library (owner review + the author's own visual pass). Renders every template x
// variant with the repo renderer, scaled up (nearest neighbour), on a checkerboard, a dark and a light background:
// one PNG per top category and background; rows = templates, columns = variants. Prints the quality verdicts and
// any lookalike pairs. Run on the build host (devhost), then pull the PNGs:
//   npx tsx scripts/cyrus/texture-library-sheets.ts OUT_DIR
import fs from "node:fs";
import path from "node:path";
import { deflateSync } from "node:zlib";
import { crc32 } from "../../lib/cyrus/textures/png";
import { render, type Raster } from "../../lib/cyrus/textures/render";
import { textureQuality } from "../../lib/cyrus/textures/quality";
import { instantiate, TOP_CATEGORIES } from "../../lib/cyrus/texture-library/compile";
import { TEMPLATES } from "../../lib/cyrus/texture-library/templates";
import { fingerprint, isColourLookalike, isNearCopy, similarity } from "../../lib/cyrus/texture-library/lookalike";

const OUT = process.argv[2] ?? "texture-library-sheets";
fs.mkdirSync(OUT, { recursive: true });
const CELL = 96, PAD = 12;

function png(w: number, h: number, rgba: Uint8Array): Buffer {
  const chunk = (type: string, data: Buffer) => { const b = Buffer.alloc(12 + data.length); b.writeUInt32BE(data.length, 0); b.write(type, 4, "ascii"); data.copy(b, 8); b.writeUInt32BE(crc32(b.subarray(4, 8 + data.length)), 8 + data.length); return b; };
  const raw = Buffer.alloc(h * (w * 4 + 1));
  for (let y = 0; y < h; y++) Buffer.from(rgba.buffer, rgba.byteOffset + y * w * 4, w * 4).copy(raw, y * (w * 4 + 1) + 1);
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 6;
