// Built-in catalog providers (pure, client-safe): the owner's sound library and the Cyrus texture templates,
// mapped into LibraryAsset. User/project assets come from ./user-assets.ts (an injected store).
import { librarySounds, type LibrarySound } from "../sound/library";
import { libraryTextures, type TextureLibraryItem } from "../texture-library/library";
import { assetRef, type LibraryAsset, type LibraryProvider } from "./types";

export function soundAsset(s: LibrarySound): LibraryAsset {
  const d = s.descriptors;
  return {
    kind: "sound", source: "builtin", id: s.id, ref: assetRef("sound", "builtin", s.id), name: s.prefix ? `${s.prefix} (${s.id})` : s.id,
    category: s.category, subcategory: null, useCases: [...s.useCases], tags: [...s.tags],
    descriptors: { durationClass: d.durationClass, intensity: d.intensity, pitchBand: d.pitchBand, character: d.character, loopable: d.loopable, channels: d.channels, duration: s.duration },
    ledger: { provenance: s.ledger.provenance, licence: null, licenceStatus: s.ledger.licenceStatus, author: null, original: false, derivedFrom: null },
    // the audio stays on the render host; the file name is not exposed to browsers
    preview: { type: "sound-render-host", libraryId: s.id, sha256: s.sha256 },
    projectId: null,
  };
}

export function textureAsset(t: TextureLibraryItem): LibraryAsset {
  const ramps = Object.fromEntries(Object.entries(t.ramps).filter(([, v]) => v)) as Record<string, string>;
  return {
    kind: "texture", source: "builtin", id: t.id, ref: assetRef("texture", "builtin", t.id), name: t.name,
    category: t.category, subcategory: t.sub, useCases: [...t.useCases], tags: [...t.tags],
    descriptors: { ...t.descriptors, template: t.templateId, quality: t.quality.verdict },
    ledger: { provenance: t.ledger.provenance, licence: t.ledger.licence, licenceStatus: t.ledger.licenceStatus, author: t.ledger.author, original: t.ledger.original, derivedFrom: t.ledger.derivedFrom },
    preview: { type: "texture-template", itemId: t.id, templateId: t.templateId, ramps, dna: t.dna, pngSha256: t.pngSha256 },
    projectId: null,
  };
}

let soundCache: LibraryAsset[] | null = null;
let textureCache: LibraryAsset[] | null = null;
export const builtinSoundAssets = (): readonly LibraryAsset[] => (soundCache ??= librarySounds().map(soundAsset));
export const builtinTextureAssets = (): readonly LibraryAsset[] => (textureCache ??= libraryTextures().map(textureAsset));

export const SoundLibraryProvider: LibraryProvider = {
  kind: "sound", sources: ["builtin"],
  list: async (_ctx, allowed) => (allowed.has("builtin") ? builtinSoundAssets() : []),
};
export const TextureLibraryProvider: LibraryProvider = {
  kind: "texture", sources: ["builtin"],
  list: async (_ctx, allowed) => (allowed.has("builtin") ? builtinTextureAssets() : []),
};
EOF

