//    library licence forbids shipping a file unchanged), plus its sound key `<ns>:<set>.<event>`
import { buildIdentifier, isNamespace, type IdentifierKind } from "../engine-core/identifiers";
import type { AssetSlot } from "../engine-core/spec";
import { SLOT_ID_RE } from "../engine-core/spec";
import { librarySound, libraryCatalogDurations } from "../sound/library";
import { checkSoundSpec, ROLE_PROFILE, SOUND_ROLES, type SoundLayer, type SoundRole, type SoundSpec } from "../sound/spec";
import type { TextureSpec } from "../textures/dsl";
