import { qualityProblems, textureQuality, type QualityReport } from "../textures/quality";
import { instantiate, type DnaPreset, type TemplateVariant } from "../texture-library/compile";
import { libraryTexture } from "../texture-library/library";
import { template } from "../texture-library/templates";
import { TEXTURE_TAXONOMY } from "../texture-library/compile";

export type Reserve = (kind: IdentifierKind, key: string) => Promise<{ fullId: string }>;
type Fail = { ok: false; error: string };

const TEX_KEY = /^[a-z][a-z0-9_]{1,31}$/;

export type UseTextureInput = {
  /** a library item (template + its ramps) or a bare template id */
  itemId?: string; templateId?: string;
  /** override ramps (any ramp of a family the template slot allows) */
  ramps?: TemplateVariant;
  /** the mod's Style DNA (a preset id or the mod's own preset object); default: the item's */
  dna?: string | DnaPreset;
  /** the asset slot / texture name in this project */
  key: string;
  namespace: string;
  purpose?: string;
};
export type UsedTexture = {
  ok: true; spec: TextureSpec; identifier: string; slot: AssetSlot; quality: QualityReport;
  provenance: { library: { kind: "texture"; itemId: string | null; templateId: string; ramps: Record<string, string | null>; dna: string }; ledger: { provenance: string; licence: string; licenceStatus: string; original: boolean; derivedFrom: string } };
};

export async function useTextureFromLibrary(input: UseTextureInput, reserve: Reserve): Promise<UsedTexture | Fail> {
  if (!isNamespace(input.namespace)) return { ok: false, error: `"${input.namespace}" is not a reserved nx_ namespace` };
  if (!TEX_KEY.test(input.key) || !SLOT_ID_RE.test(input.key)) return { ok: false, error: "the texture key must be 2-32 lowercase letters, digits and underscores, starting with a letter" };
  const item = input.itemId ? libraryTexture(input.itemId) : null;
  if (input.itemId && !item) return { ok: false, error: `unknown library texture ${input.itemId}` };
  const t = template(item?.templateId ?? input.templateId ?? "");
  if (!t) return { ok: false, error: `unknown texture template ${String(input.templateId)}` };
  const base = item ? (Object.fromEntries(Object.entries(item.ramps).filter(([, v]) => v)) as TemplateVariant) : t.variants[0];
  const inst = instantiate(t, { name: input.key, ramps: { ...base, ...(input.ramps ?? {}) }, dna: input.dna ?? item?.dna });
  if (!inst.ok) return inst;
  const quality = textureQuality(render(inst.spec), { profile: t.profile, tileable: t.tileable, framed: t.framed });
  if (quality.verdict === "fail") return { ok: false, error: `this combination fails the texture checks: ${qualityProblems(quality)[0]}` };
  const path = `${t.category === "blocks" ? "block" : "item"}/${input.key}`;
  const built = buildIdentifier(input.namespace, "model", path);
  if (!built.ok) return { ok: false, error: built.error };
  const r = await reserve("model", path);
  if (r.fullId !== built.id) return { ok: false, error: `reserved ${r.fullId}, expected ${built.id} (wrong project namespace?)` };
  const L = TEXTURE_TAXONOMY.ledger;
  return {
    ok: true, spec: inst.spec, identifier: r.fullId, quality,
    slot: { id: input.key, kind: "texture", purpose: (input.purpose ?? `${item?.name ?? t.name} from the Cyrus texture library`).slice(0, 300), source: "library", requirementIds: [] },
    provenance: {
      library: { kind: "texture", itemId: item?.id ?? null, templateId: t.id, ramps: inst.ramps, dna: inst.dna },
      // recolouring an original Cyrus template with library ramps keeps it a Cyrus original
      ledger: { provenance: L.builtinProvenance, licence: L.builtinLicence, licenceStatus: L.builtinLicenceStatus, original: true, derivedFrom: `template:${t.id}` },
    },
  };
}

export type UseSoundInput = {
  id: string; set: string; event: string; role: SoundRole; subtitle?: string; namespace: string;
