export type UsedSound = { ok: true; spec: SoundSpec; layer: SoundLayer; identifier: string; slot: AssetSlot; provenance: { library: { kind: "sound"; id: string; sha256: string }; ledger: { provenance: string; licenceStatus: string; original: false } } };

/** A SoundSpec layer that plays a library sound (to add to an existing variant). */
export function soundLayerFrom(id: string, opts: { pitch?: number; length?: number | null; gain?: number } = {}): SoundLayer | null {
  const s = librarySound(id);
  if (!s) return null;
  return { source: `lib:${id}`, start: 0, gain: opts.gain ?? 0, pitch: opts.pitch ?? -1, trimStart: 0, length: opts.length ?? null, fadeIn: 0, fadeOut: 0, seed: 1, params: {} };
}

export async function useSoundFromLibrary(input: UseSoundInput, reserve: Reserve): Promise<UsedSound | Fail> {
  if (!input.libraryCleared) return { ok: false, error: "the sound library is not cleared for customer builds yet (owner licence decision)" };
  if (!isNamespace(input.namespace)) return { ok: false, error: `"${input.namespace}" is not a reserved nx_ namespace` };
  if (!(SOUND_ROLES as readonly string[]).includes(input.role)) return { ok: false, error: `role must be one of ${SOUND_ROLES.join(", ")}` };
