//  - ancillary chunks (tEXt, iTXt, zTXt, eXIf, iCCP, tIME, ...) are skipped and reported: the upload is RE-ENCODED
//    from pixels, so no metadata survives; an unknown CRITICAL chunk is refused
import { inflateSync } from "node:zlib";
import { crc32 } from "../textures/png";
import type { Raster } from "../textures/render";

export type DecodeLimits = { maxBytes: number; sizes: readonly number[]; maxChunks: number };
export type Decoded = { ok: true; raster: Raster; width: number; height: number; colorType: number; bitDepth: number; skipped: string[] } | { ok: false; code: string; error: string };

const SIG = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
const CHANNELS: Record<number, number> = { 0: 1, 2: 3, 3: 1, 4: 2, 6: 4 };

export function decodePng(buf: Buffer, lim: DecodeLimits): Decoded {
  const no = (code: string, error: string): Decoded => ({ ok: false, code, error });
  if (buf.length > lim.maxBytes) return no("too_large", `the file is ${buf.length} bytes; the limit is ${lim.maxBytes}`);
  if (buf.length < 8 + 25 || !buf.subarray(0, 8).equals(SIG)) return no("not_png", "not a PNG file");
  let off = 8, n = 0, w = 0, h = 0, depth = 0, ct = -1, sawEnd = false;
  let palette: Buffer | null = null, trns: Buffer | null = null;
  const idat: Buffer[] = [], skipped: string[] = [];
  while (off < buf.length) {
    if (++n > lim.maxChunks) return no("too_many_chunks", `more than ${lim.maxChunks} chunks`);
    if (off + 12 > buf.length) return no("truncated", "truncated chunk");
    const len = buf.readUInt32BE(off), type = buf.toString("latin1", off + 4, off + 8);
    if (!/^[A-Za-z]{4}$/.test(type)) return no("bad_chunk", "malformed chunk type");
    if (len > buf.length - off - 12) return no("truncated", `chunk ${type} runs past the end of the file`);
    const data = buf.subarray(off + 8, off + 8 + len);
    if (crc32(buf.subarray(off + 4, off + 8 + len)) !== buf.readUInt32BE(off + 8 + len)) return no("bad_crc", `chunk ${type} is corrupt (CRC mismatch)`);
    off += 12 + len;
    if (n === 1 && type !== "IHDR") return no("bad_png", "IHDR must be the first chunk");
    if (type === "IHDR") {
      if (n !== 1 || len !== 13) return no("bad_png", "bad IHDR");
      w = data.readUInt32BE(0); h = data.readUInt32BE(4); depth = data[8]; ct = data[9];
      if (data[10] !== 0 || data[11] !== 0) return no("bad_png", "unknown compression or filter method");
      if (data[12] !== 0) return no("interlaced", "interlaced PNGs are not supported; save it non-interlaced");
      if (w !== h || !lim.sizes.includes(w)) return no("bad_dimensions", `${w}x${h} is not allowed; use a square ${lim.sizes.join(", ")} px texture`);
      if (!(ct in CHANNELS)) return no("bad_png", `unknown colour type ${ct}`);
      if (ct === 3 ? ![1, 2, 4, 8].includes(depth) : depth !== 8) return no("bad_depth", depth === 16 ? "16-bit PNGs are not supported; export 8-bit" : `bit depth ${depth} is not supported for colour type ${ct}`);
    } else if (type === "PLTE") { if (len % 3 || len === 0 || len > 768) return no("bad_png", "bad palette"); palette = data; }
    else if (type === "tRNS") trns = data;
    else if (type === "IDAT") idat.push(data);
    else if (type === "IEND") { sawEnd = true; break; }
    else if (type[0] === type[0].toUpperCase()) return no("bad_chunk", `unknown critical chunk ${type}`);
    else skipped.push(type);
  }
  if (!sawEnd) return no("truncated", "missing IEND");
  if (!idat.length) return no("bad_png", "no image data");
  if (ct === 3 && !palette) return no("bad_png", "palette image without PLTE");
  const ch = CHANNELS[ct], bpp = Math.max(1, (ch * depth) >> 3), stride = Math.ceil((w * ch * depth) / 8);
  const expected = h * (stride + 1);
  let raw: Buffer;
  try { raw = inflateSync(Buffer.concat(idat), { maxOutputLength: expected + 1 }); }
  catch (e) { return no((e as { code?: string }).code === "ERR_BUFFER_TOO_LARGE" || /larger than|maxOutputLength/i.test(String(e)) ? "decompression_bomb" : "bad_zlib", "the image data inflates past what its header allows (or is corrupt)"); }
  if (raw.length !== expected) return no(raw.length > expected ? "decompression_bomb" : "truncated", `image data is ${raw.length} bytes, expected ${expected}`);
  // unfilter
  const out = Buffer.alloc(h * stride); let prev = Buffer.alloc(stride);
  for (let y = 0; y < h; y++) {
    const f = raw[y * (stride + 1)], line = raw.subarray(y * (stride + 1) + 1, (y + 1) * (stride + 1)), cur = out.subarray(y * stride, (y + 1) * stride);
    for (let i = 0; i < stride; i++) {
      const a = i >= bpp ? cur[i - bpp] : 0, b = prev[i], c = i >= bpp ? prev[i - bpp] : 0;
      let v = line[i];
      if (f === 1) v += a; else if (f === 2) v += b; else if (f === 3) v += (a + b) >> 1;
      else if (f === 4) { const p = a + b - c, pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c); v += pa <= pb && pa <= pc ? a : pb <= pc ? b : c; }
      else if (f !== 0) return no("bad_png", `unknown filter type ${f}`);
      cur[i] = v & 255;
    }
    prev = cur;
  }
  const px = new Uint8ClampedArray(w * h * 4);
  const sample = (row: Buffer, x: number) => { const bit = x * depth; return (row[bit >> 3] >> (8 - depth - (bit & 7))) & ((1 << depth) - 1); };
  for (let y = 0; y < h; y++) {
    const row = out.subarray(y * stride, (y + 1) * stride);
    for (let x = 0; x < w; x++) {
      const o = (y * w + x) * 4;
      if (ct === 6) { row.copy(Buffer.from(px.buffer, o, 4), 0, x * 4, x * 4 + 4); }
      else if (ct === 2) { px[o] = row[x * 3]; px[o + 1] = row[x * 3 + 1]; px[o + 2] = row[x * 3 + 2]; px[o + 3] = trns && trns.length >= 6 && trns.readUInt16BE(0) === row[x * 3] && trns.readUInt16BE(2) === row[x * 3 + 1] && trns.readUInt16BE(4) === row[x * 3 + 2] ? 0 : 255; }
      else if (ct === 0) { const g = row[x]; px[o] = px[o + 1] = px[o + 2] = g; px[o + 3] = trns && trns.length >= 2 && trns.readUInt16BE(0) === g ? 0 : 255; }
      else if (ct === 4) { px[o] = px[o + 1] = px[o + 2] = row[x * 2]; px[o + 3] = row[x * 2 + 1]; }
      else { const i = sample(row, x); if (i * 3 + 2 >= palette!.length) return no("bad_png", "palette index out of range"); px[o] = palette![i * 3]; px[o + 1] = palette![i * 3 + 1]; px[o + 2] = palette![i * 3 + 2]; px[o + 3] = trns && i < trns.length ? trns[i] : 255; }
    }
  }
  return { ok: true, raster: { size: w, px }, width: w, height: h, colorType: ct, bitDepth: depth, skipped };
}
