// Cyrus texture library (R1), pure tests: taxonomy coverage, Style DNA ramps, every template valid + quality-passing
// + deterministic (manifest hashes re-derived), no lookalikes, near-copy check, ledger rules, tile quality profile.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { checkSpec } from "../lib/cyrus/textures/dsl";
import { render, type Raster } from "../lib/cyrus/textures/render";
import { encodePng } from "../lib/cyrus/textures/png";
import { textureQuality } from "../lib/cyrus/textures/quality";
import { canonicalJson, sha256Hex } from "../lib/cyrus/assets/textures";
import { checkTemplate, instantiate, ramps, SUBCATEGORIES, TEXTURE_TAXONOMY, TEXTURE_USE_CASES, darkenTo, variantName } from "../lib/cyrus/texture-library/compile";
import { TEMPLATES, template } from "../lib/cyrus/texture-library/templates";
import { libraryTextures, librarySpec, textureManifest } from "../lib/cyrus/texture-library/library";
import { buildManifest } from "../lib/cyrus/texture-library/build";
import { checkNearCopy, fingerprint, isColourLookalike, isNearCopy, similarity } from "../lib/cyrus/texture-library/lookalike";

const hex = (h: string) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
const lin = (c: number) => { const s = c / 255; return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4); };
const lum = (h: string) => { const [r, g, b] = hex(h); return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b); };

describe("texture taxonomy", () => {
  it("every subcategory has library items and every item's category, subcategory and use cases are in the taxonomy", () => {
    const items = libraryTextures();
    for (const sc of SUBCATEGORIES) assert.ok(items.some((i) => `${i.category}/${i.sub}` === sc), `no library item in ${sc}`);
    for (const i of items) {
      assert.ok(SUBCATEGORIES.includes(`${i.category}/${i.sub}`), `${i.id}: unknown ${i.category}/${i.sub}`);
      assert.ok(i.useCases.length > 0, `${i.id} has no use case`);
      for (const u of i.useCases) assert.ok(TEXTURE_USE_CASES.includes(u), `${i.id}: unknown use case ${u}`);
    }
    for (const u of TEXTURE_USE_CASES) assert.ok(items.some((i) => i.useCases.includes(u)), `use case ${u} has no item`);
  });
  it("entity-skin subcategories carry UV layout notes", () => {
    for (const s of TEXTURE_TAXONOMY.categories.find((c) => c.id === "entity_skins")!.subcategories) assert.ok((s.uvNotes ?? "").length > 40, s.id);
  });
  it("ramps are 5 shades, dark to light, each step a deliberate one (no grain inside a ramp)", () => {
    for (const r of ramps()) {
      assert.equal(r.shades.length, 5, r.id);
      for (const s of r.shades) assert.match(s, /^#[0-9a-f]{6}$/, r.id);
      for (let i = 1; i < 5; i++) {
        assert.ok(lum(r.shades[i]) > lum(r.shades[i - 1]), `${r.id} shade ${i} is not lighter`);
        const [a, b] = [hex(r.shades[i - 1]), hex(r.shades[i])];
        assert.ok(Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]) > 24, `${r.id} steps ${i - 1}->${i} are closer than the quality bar's grain distance`);
      }
    }
  });
  it("Style DNA presets reference known outline rules, light directions and noise levels", () => {
    const dna = TEXTURE_TAXONOMY.styleDna;
    for (const p of dna.presets) {
      assert.ok(dna.outlineRules.some((o) => o.id === p.outline), p.id);
      assert.ok(dna.lightDirections.includes(p.light), p.id);
      assert.ok(dna.noiseLevels.some((n) => n.id === p.noise), p.id);
    }
  });
  it("synonyms point at words the library actually uses", () => {
    const vocab = new Set(libraryTextures().flatMap((i) => [...i.tags, i.sub, i.category, ...i.useCases]));
    const missing = Object.entries(TEXTURE_TAXONOMY.synonyms).filter(([, v]) => !vocab.has(v)).map(([k, v]) => `${k}->${v}`);
    assert.ok(missing.length <= 3, `synonyms to unused words: ${missing.join(", ")}`);
  });
});

describe("texture templates", () => {
  it("at least 80 original templates and every template is structurally valid", () => {
    assert.ok(TEMPLATES.length >= 80, `${TEMPLATES.length} templates`);
    assert.equal(new Set(TEMPLATES.map((t) => t.id)).size, TEMPLATES.length);
    for (const t of TEMPLATES) assert.deepEqual(checkTemplate(t), [], t.id);
  });
  it("every variant compiles to a spec that passes checkSpec and the quality bar (never fail)", () => {
    for (const t of TEMPLATES) for (const v of t.variants) {
      const r = instantiate(t, { ramps: v });
      assert.ok(r.ok, `${t.id}: ${!r.ok && r.error}`);
      if (!r.ok) continue;
      assert.ok(checkSpec(JSON.parse(JSON.stringify(r.spec))).ok, `${r.spec.name} checkSpec`);
      const q = textureQuality(render(r.spec), { profile: t.profile, tileable: t.tileable, framed: t.framed });
      assert.notEqual(q.verdict, "fail", `${r.spec.name}: ${JSON.stringify(q.checks.filter((c) => c.status === "fail"))}`);
      // items pass outright except particles (no outline by design) - warns are listed in the manifest
      if (t.category === "items") assert.equal(q.verdict, "pass", `${r.spec.name} should pass every check`);
    }
  });
  it("every template accepts every Style DNA preset and every ramp of an allowed family", () => {
    for (const t of TEMPLATES) {
      for (const p of TEXTURE_TAXONOMY.styleDna.presets) {
        const r = instantiate(t, { dna: p.id });
        assert.ok(r.ok, `${t.id} x ${p.id}`);
        if (r.ok && t.outline && p.outline === "black") assert.equal(r.spec.palette.ol, "#0e0d12");
        if (r.ok && p.outline === "none") assert.ok(!r.spec.ops.some((o) => o.op === "outline"), `${t.id} x none`);
        if (r.ok) assert.notEqual(textureQuality(render(r.spec), { profile: t.profile, tileable: t.tileable, framed: t.framed }).verdict, "fail", `${t.id} x ${p.id}`);
      }
      for (const slot of ["m", "h", "x"] as const) for (const fam of t.slots[slot] ?? []) for (const rp of ramps().filter((r) => r.family === fam)) {
        assert.ok(instantiate(t, { ramps: { ...t.variants[0], [slot]: rp.id } }).ok, `${t.id}.${slot}=${rp.id}`);
      }
    }
  });
  it("rejects a ramp from a family the slot does not allow, and an unknown DNA preset", () => {
    const sword = template("sword")!;
    const r = instantiate(sword, { ramps: { m: "oak" } });
    assert.equal(r.ok, false);
    assert.equal(instantiate(sword, { dna: "nope" }).ok, false);
  });
  it("tinted outlines are dark enough for the quality bar's outline rule", () => {
    for (const r of ramps()) assert.ok(lum(darkenTo(r.shades[0])) <= 0.12, r.id);
  });
  it("variant names are unique and readable", () => {
    const names = TEMPLATES.flatMap((t) => t.variants.map((v) => variantName(t, v)));
    assert.equal(new Set(names).size, names.length);
    assert.ok(names.includes("sword_iron") && names.includes("bread") && names.includes("fur") && names.includes("ring_gold_ruby"));
    for (const n of names) assert.match(n, /^[a-z][a-z0-9_]{1,31}$/);
  });
  it("the library has no lookalikes: no two templates are near-copies, no two variants of one template look the same", () => {
    const fps = TEMPLATES.flatMap((t) => t.variants.map((v) => { const r = instantiate(t, { ramps: v }); assert.ok(r.ok); return { t: t.id, id: r.ok ? r.spec.name : "", fp: fingerprint(render(r.ok ? r.spec : (undefined as never))) }; }));
    const bad: string[] = [];
    for (let i = 0; i < fps.length; i++) for (let j = i + 1; j < fps.length; j++) {
      const s = similarity(fps[i].fp, fps[j].fp);
      if (fps[i].t !== fps[j].t ? isNearCopy(s) : isColourLookalike(s)) bad.push(`${fps[i].id}~${fps[j].id}`);
    }
    assert.deepEqual(bad, []);
  });
});

describe("texture library manifest", () => {
  it("is up to date with the templates (same items, specs, PNG hashes)", () => {
    assert.deepEqual(JSON.parse(JSON.stringify(buildManifest())), textureManifest());
  });
  it("every item re-derives to its recorded spec and PNG hashes (deterministic render)", () => {
    for (const i of libraryTextures()) {
      const spec = librarySpec(i);
      assert.ok(spec, i.id);
      assert.equal(sha256Hex(canonicalJson(spec)), i.specSha256, `${i.id} spec`);
      assert.equal(sha256Hex(encodePng(render(spec!))), i.pngSha256, `${i.id} png`);
      assert.equal(sha256Hex(encodePng(render(spec!))), i.pngSha256, `${i.id} png again`);
    }
  });
  it("counts: >= 250 items over >= 80 templates; every top category is populated", () => {
    const m = textureManifest();
    assert.ok(m.items.length >= 250 && m.templateCount >= 80, `${m.items.length} / ${m.templateCount}`);
    for (const c of ["items", "blocks", "entity_skins", "gui", "particles"]) assert.ok(m.items.filter((i) => i.category === c).length >= 10, c);
  });
  it("ledger: built-ins are Cyrus originals with the exact provenance string; descriptors are measured", () => {
    for (const i of libraryTextures()) {
      assert.equal(i.ledger.provenance, "authored by Cyrus (2026-10-10), original");
      assert.equal(i.ledger.original, true);
      assert.equal(i.ledger.derivedFrom, `template:${i.templateId}`);
      assert.equal(i.quality.checks.vanilla_lookalike ?? "not_run", "not_run");
      const q = textureQuality(render(librarySpec(i)!), { profile: template(i.templateId)!.profile, tileable: i.descriptors.tileable, framed: template(i.templateId)!.framed });
      assert.equal(i.descriptors.paletteSize, q.checks.find((c) => c.id === "palette_size")!.value);
      assert.equal(i.descriptors.transparency === "opaque", q.checks.find((c) => c.id === "transparency")!.value === 1);
    }
  });
});

describe("near-copy check (vanilla lookalike stub)", () => {
  const sword = render(librarySpec(libraryTextures().find((i) => i.id === "sword_iron")!)!);
  const recolour = render(librarySpec(libraryTextures().find((i) => i.id === "sword_ruby")!)!);
  const potion = render(librarySpec(libraryTextures().find((i) => i.id === "flask_ruby")!)!);
  it("reports not_run without reference fingerprints (never claims clean)", () => {
    assert.equal(checkNearCopy(sword, []).status, "not_run");
  });
  it("rejects the same drawing, also when recoloured; passes a different drawing", () => {
    assert.equal(checkNearCopy(sword, [fingerprint(sword)]).status, "fail");
    assert.equal(checkNearCopy(recolour, [fingerprint(sword)]).status, "fail");
    assert.equal(checkNearCopy(potion, [fingerprint(sword)]).status, "pass");
  });
  it("a one-pixel edit is still a near-copy", () => {
    const px = new Uint8ClampedArray(sword.px); px[(8 * 16 + 8) * 4 + 3] = 0;
    assert.equal(checkNearCopy({ size: 16, px }, [fingerprint(sword)]).status, "fail");
  });
});

describe("quality bar tile profile", () => {
