    for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) { const c = f(x, y), i = (y * 16 + x) * 4; px[i] = c[0]; px[i + 1] = c[1]; px[i + 2] = c[2]; px[i + 3] = 255; }
