// Cyrus unified asset catalog (R1), pure tests (no DB, no network): realistic searches across sounds + textures,
// facets / pagination / similar, the browse gate matrix (plans x kinds x sources x signed-in), the catalog service
// with fake providers and plan lookup, user/project assets through a fake store, use-in-project namespacing, and
// PNG upload validation (valid, oversize, bad dimensions, decompression bomb, metadata stripped, ...).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { deflateSync } from "node:zlib";
import { crc32, encodePng } from "../lib/cyrus/textures/png";
import { render } from "../lib/cyrus/textures/render";
import { libraryTextures, librarySpec } from "../lib/cyrus/texture-library/library";
import { librarySounds } from "../lib/cyrus/sound/library";
import { builtinSoundAssets, builtinTextureAssets, SoundLibraryProvider, TextureLibraryProvider } from "../lib/cyrus/library/providers";
import { searchAssets, similarAssets, expandTerm } from "../lib/cyrus/library/search";
import { canBrowse } from "../lib/cyrus/library/gate";
import { browseLibrary, similarInLibrary, type CatalogDeps } from "../lib/cyrus/library/catalog";
import { userAssetProviders, latestRows, type UserAssetRow } from "../lib/cyrus/library/user-assets";
import { useSoundFromLibrary, useTextureFromLibrary, soundLayerFrom, type Reserve } from "../lib/cyrus/library/use-in-project";
import { decodePng } from "../lib/cyrus/library/png-decode";
import { uploadTexture, validateTextureUpload, UPLOAD_LIMITS, type UploadDeps } from "../lib/cyrus/library/upload";
import { LIBRARY_KINDS, LIBRARY_SOURCES, type LibraryAsset } from "../lib/cyrus/library/types";
import { namespaceFromSeed } from "../lib/cyrus/engine-core/identifiers";
import type { ModSpec } from "../lib/cyrus/engine-core/spec";

const ALL = [...builtinTextureAssets(), ...builtinSoundAssets()];
const top = (text: string, n = 10, kinds?: LibraryAsset["kind"][]) => searchAssets(ALL, { text, limit: n, ...(kinds ? { kinds } : {}) }).items;

describe("unified search: realistic queries", () => {
  it("'sword' -> swords first, then other blades; sounds join via synonyms (melee/whoosh)", () => {
    const r = searchAssets(ALL, { text: "sword", limit: 20 });
    assert.ok(r.items.slice(0, 6).every((a) => a.kind === "texture" && a.descriptors.template === "sword"), r.items.slice(0, 6).map((a) => a.id).join());
    assert.ok((r.facets.kind.sound ?? 0) > 0, "sword should also find melee / whoosh sounds");
  });
  it("'iron' -> iron materials (sword, ore, plate, ingot...)", () => {
    const ids = searchAssets(ALL, { text: "iron", limit: 200, kinds: ["texture"] }).items.map((a) => a.id);
    for (const id of ["sword_iron", "ore_iron", "metal_plate_iron", "ingot_iron", "helmet_iron"]) assert.ok(ids.includes(id), id);
    assert.ok(top("iron", 10, ["texture"]).every((a) => a.tags.includes("iron")));
  });
  it("'stone' -> stone blocks first", () => {
    const t = top("stone", 8, ["texture"]);
    assert.ok(t.every((a) => a.category === "blocks" || a.tags.includes("stone")), t.map((a) => a.id).join());
    assert.ok(t.some((a) => a.id === "cobble_stone"));
  });
  it("'gui button' -> buttons first (gui expands to the GUI family, button is exact)", () => {
    const t = top("gui button", 6, ["texture"]);
    assert.ok(t.length >= 6 && t.every((a) => a.subcategory === "button"), t.map((a) => a.id).join());
  });
  it("'potion' -> flasks, vials and bottles", () => {
    const t = searchAssets(ALL, { text: "potion", kinds: ["texture"], limit: 50 }).items;
    assert.ok(t.length >= 15 && t.slice(0, 15).every((a) => a.subcategory === "potion"));
  });
  it("'ore' -> the ore blocks (8 ramps), nothing unrelated above them", () => {
    const t = top("ore", 8, ["texture"]);
    assert.equal(t.filter((a) => a.descriptors.template === "ore").length, 8);
  });
  it("across kinds: 'gun' finds the handgun texture AND gunshot / reload sounds", () => {
    const r = searchAssets(ALL, { text: "gun", limit: 200 });
    assert.ok(r.items.some((a) => a.kind === "texture" && a.descriptors.template === "handgun"));
    assert.ok(r.items.some((a) => a.kind === "sound" && a.category === "weapons"));
    assert.ok(expandTerm("gun").includes("handgun") && expandTerm("gun").includes("gunshot"));
  });
  it("every query word must match; nonsense finds nothing", () => {
    assert.equal(searchAssets(ALL, { text: "sword zzqx" }).total, 0);
    assert.equal(searchAssets(ALL, { text: "" }).total, ALL.length);
  });
  it("filters, facets and pagination are consistent", () => {
    const all = searchAssets(ALL, { kinds: ["texture"], category: "blocks", limit: 200 });
    assert.equal(all.total, libraryTextures().filter((i) => i.category === "blocks").length);
    assert.equal(all.facets.category.blocks, all.total);
    const p1 = searchAssets(ALL, { kinds: ["texture"], category: "blocks", limit: 10, offset: 0 }).items.map((a) => a.ref);
    const p2 = searchAssets(ALL, { kinds: ["texture"], category: "blocks", limit: 10, offset: 10 }).items.map((a) => a.ref);
    assert.deepEqual([...p1, ...p2], all.items.slice(0, 20).map((a) => a.ref));
    const opaque = searchAssets(ALL, { kinds: ["texture"], descriptors: { transparency: ["opaque"] }, limit: 200 });
    assert.ok(opaque.total > 30 && opaque.items.every((a) => a.descriptors.transparency === "opaque"));
    assert.ok(Object.keys(all.facets.descriptors.material ?? {}).length > 5);
    const loud = searchAssets(ALL, { kinds: ["sound"], descriptors: { intensity: ["loud"] }, limit: 200 });
    assert.ok(loud.total > 0 && loud.items.every((a) => a.descriptors.intensity === "loud"));
  });
  it("similar to sword_iron: other melee weapons first, not just recolours", () => {
    const s = similarAssets("texture/builtin/sword_iron", ALL, 8);
    assert.ok(s.length >= 5);
    assert.ok(s.slice(0, 3).some((a) => a.descriptors.template !== "sword"));
    assert.ok(s.every((a) => a.kind === "texture" && a.useCases.includes("melee_weapon")));
    assert.deepEqual(similarAssets("texture/builtin/nope", ALL), []);
  });
  it("sound assets keep the library ledger and never expose the file name", () => {
    for (const a of builtinSoundAssets()) {
      assert.equal(a.ledger.original, false);
      assert.match(a.ledger.licenceStatus, /unverified/);
      assert.ok(!JSON.stringify(a.preview).includes(".mp3"));
    }
    assert.equal(builtinSoundAssets().length, librarySounds().length);
  });
});

describe("browse gate matrix", () => {
  const PLANS: [unknown, string][] = [["free", "free"], ["katara", "katara"], ["saka", "saka"], ["all", "all"], ["Yakko", "all"], ["platinum", "unknown"], [null, "unknown"], [undefined, "unknown"]];
  const expected = (plan: string, kind: string, source: string, signedIn: boolean): string => {
    if (!signedIn) return "sign_in";
    if (source === "project") return "ok";
    if (plan === "unknown") return "plan_unknown";
    const rank: Record<string, number> = { free: 0, katara: 1, saka: 2, all: 3 };
    return rank[plan] >= (kind === "sound" ? 2 : 3) ? "ok" : "asset_locked";
  };
  it("every plan x kind x source x signed-in combination", () => {
    let n = 0;
    for (const [raw, plan] of PLANS) for (const kind of LIBRARY_KINDS) for (const source of LIBRARY_SOURCES) for (const signedIn of [true, false]) {
      const d = canBrowse({ signedIn, plan: raw }, kind, source);
      assert.equal(d.ok ? "ok" : d.code, expected(plan, kind, source, signedIn), `${String(raw)} ${kind} ${source} ${signedIn}`);
      if (!d.ok && d.code === "asset_locked") assert.equal(d.needs, kind === "sound" ? "saka" : "all");
      n++;
    }
    assert.equal(n, PLANS.length * 3 * 3 * 2);
  });
});

const rows = (userId: string): UserAssetRow[] => [
  { id: "a1", projectId: "cpA", assetKey: "my_sword", kind: "texture", sha256: "1".repeat(64), size: 100, mime: "image/png", path: "x", origin: "upload", provenance: { width: 16, ledger: { original: true, provenance: "mine" }, moderation: { status: "unreviewed" } }, createdAt: "2026-10-10T10:00:00Z" },
  { id: "a2", projectId: "cpA", assetKey: "my_sword", kind: "texture", sha256: "2".repeat(64), size: 100, mime: "image/png", path: "y", origin: "upload", provenance: {}, createdAt: "2026-10-10T09:00:00Z" },
  { id: "a3", projectId: "cpB", assetKey: "banshee", kind: "sound", sha256: "3".repeat(64), size: 900, mime: "application/json", path: "z", origin: "generated", provenance: { tags: ["ghost"] }, createdAt: "2026-10-10T08:00:00Z" },
  { id: "a4", projectId: "cpB", assetKey: "rig", kind: "model", sha256: "4".repeat(64), size: 9, mime: null, path: null, origin: "generated", provenance: null, createdAt: "2026-10-10T08:00:00Z" },
].map((r) => ({ ...r, id: `${userId}-${r.id}` }));
const fakeStore = { calls: 0, async listForUser(userId: string) { this.calls++; return userId === "u1" ? rows("u1") : []; } };
const deps = (plan: unknown, store = fakeStore): CatalogDeps => ({ providers: [SoundLibraryProvider, TextureLibraryProvider, ...userAssetProviders(store)], planOf: async () => { if (plan === "throw") throw new Error("billing down"); return plan; } });

describe("catalog service (fake providers and plan lookup)", () => {
  it("top plan sees sounds, textures and the user's own assets; the store is read once per request", async () => {
    fakeStore.calls = 0;
    const r = await browseLibrary(deps("all"), { userId: "u1", projectId: "cpA", query: { limit: 200 } });
    assert.equal(fakeStore.calls, 1);
    assert.ok((r.facets.kind.sound ?? 0) > 0 && (r.facets.kind.texture ?? 0) > 0);
    assert.equal(r.facets.source.project, 1); // my_sword (latest row only)
    assert.equal(r.facets.source.user, 1); // banshee from the other project; the model row is skipped
    assert.deepEqual(r.denied.filter((d) => d.kind !== "model"), []);
  });
  it("Saka: sounds yes, textures no (denied with needs=all), own project textures still visible", async () => {
    const r = await browseLibrary(deps("saka"), { userId: "u1", projectId: "cpA", query: { limit: 200 } });
    assert.ok((r.facets.kind.sound ?? 0) > 0);
    assert.deepEqual(r.items.filter((a) => a.kind === "texture").map((a) => a.source), ["project"]);
    assert.ok(r.denied.some((d) => d.kind === "texture" && d.source === "builtin" && d.code === "asset_locked" && d.needs === "all"));
  });
  it("free / Katara: only what is already in the project", async () => {
    for (const plan of ["free", "katara"]) {
      const r = await browseLibrary(deps(plan), { userId: "u1", projectId: "cpA", query: { limit: 200 } });
      assert.deepEqual([...new Set(r.items.map((a) => a.source))], ["project"], plan);
    }
  });
  it("unknown plan (lookup throws) fails closed; signed out sees nothing", async () => {
    const r = await browseLibrary(deps("throw"), { userId: "u1", projectId: "cpA" });
    assert.ok(r.items.every((a) => a.source === "project"));
    assert.ok(r.denied.some((d) => d.code === "plan_unknown"));
    const out = await browseLibrary(deps("all"), { userId: null, query: { text: "sword" } });
    assert.equal(out.total, 0);
    assert.ok(out.denied.every((d) => d.code === "sign_in"));
  });
  it("similarInLibrary respects the gate", async () => {
    assert.ok((await similarInLibrary(deps("all"), { userId: "u1", ref: "texture/builtin/sword_iron" })).length > 0);
    assert.deepEqual(await similarInLibrary(deps("saka"), { userId: "u1", ref: "texture/builtin/sword_iron" }), []);
  });
  it("user assets: newest row per key, customer assets are never marked original", async () => {
    assert.equal(latestRows(rows("u1")).filter((r) => r.assetKey === "my_sword")[0].id, "u1-a1");
    const r = await browseLibrary(deps("all"), { userId: "u1", projectId: "cpA", query: { sources: ["project", "user"], limit: 50 } });
    const mine = r.items.find((a) => a.id === "cpA:my_sword")!;
    assert.equal(mine.ledger.original, false);
    assert.equal(mine.ledger.provenance, "mine");
    assert.equal(mine.descriptors.moderation, "unreviewed");
    assert.equal(mine.preview.type, "texture-asset");
    assert.ok(r.items.find((a) => a.id === "cpB:banshee")!.tags.includes("ghost"));
  });
});

describe("use in project (namespaced ids)", () => {
  const ns = namespaceFromSeed("cp-test-project");
  const reserved: string[] = [];
  const reserve: Reserve = async (kind, key) => { reserved.push(`${kind}:${key}`); return { fullId: kind === "sound" || kind === "model" ? `${ns}:${key}` : `${ns}.${key}` }; };
  it("instantiates a template with a chosen ramp and the mod's Style DNA, reserving <ns>:item/<key>", async () => {
    const r = await useTextureFromLibrary({ itemId: "sword_iron", ramps: { m: "emerald" }, dna: "pixel_bold", key: "jade_blade", namespace: ns }, reserve);
    assert.ok(r.ok, !r.ok ? r.error : "");
    if (!r.ok) return;
    assert.equal(r.spec.name, "jade_blade");
    assert.equal(r.identifier, `${ns}:item/jade_blade`);
    assert.equal(r.spec.palette.ol, "#0e0d12");
    assert.equal(r.spec.palette.m3, "#20a75b");
    assert.equal(r.slot.source, "library");
    assert.equal(r.provenance.library.templateId, "sword");
    assert.equal(r.provenance.ledger.original, true);
    assert.ok(reserved.includes("model:item/jade_blade"));
    const spec: Pick<ModSpec, "assets"> = { assets: [r.slot] };
    assert.equal(spec.assets[0].id, "jade_blade");
  });
  it("a block template reserves block/<key>; a custom DNA object works", async () => {
    const r = await useTextureFromLibrary({ templateId: "bricks", key: "red_wall", namespace: ns, dna: { id: "mod_dna", label: "Mod", outline: "none", light: "top_left", noise: "grit", rampSteps: 5, note: "" } }, reserve);
    assert.ok(r.ok && r.identifier === `${ns}:block/red_wall`);
    assert.ok(r.ok && r.spec.ops.some((o) => o.op === "noise"));
  });
  it("refuses bad keys, unknown items, wrong-family ramps, a foreign namespace and a mismatching reservation", async () => {
    assert.equal((await useTextureFromLibrary({ itemId: "sword_iron", key: "Bad Key", namespace: ns }, reserve)).ok, false);
    assert.equal((await useTextureFromLibrary({ itemId: "nope", key: "x1", namespace: ns }, reserve)).ok, false);
    assert.equal((await useTextureFromLibrary({ itemId: "sword_iron", ramps: { m: "oak" }, key: "x1", namespace: ns }, reserve)).ok, false);
    assert.equal((await useTextureFromLibrary({ itemId: "sword_iron", key: "x1", namespace: "minecraft" }, reserve)).ok, false);
    const other: Reserve = async (_k, key) => ({ fullId: `nx_00000000:${key}` });
    const r = await useTextureFromLibrary({ itemId: "sword_iron", key: "x2", namespace: ns }, other);
    assert.ok(!r.ok && /namespace/.test(r.error));
  });
  it("a library sound becomes a valid SoundSpec layer (transformed, licence rule) with <ns>:<set>.<event>", async () => {
    const id = librarySounds().find((s) => s.category === "weapons")!.id;
    assert.equal((await useSoundFromLibrary({ id, set: "blaster", event: "fire", role: "fire", namespace: ns, libraryCleared: false }, reserve)).ok, false);
    const r = await useSoundFromLibrary({ id, set: "blaster", event: "fire", role: "fire", subtitle: "Blaster fires", namespace: ns, libraryCleared: true }, reserve);
    assert.ok(r.ok, !r.ok ? r.error : "");
    if (!r.ok) return;
    assert.equal(r.identifier, `${ns}:blaster.fire`);
    assert.equal(r.layer.source, `lib:${id}`);
    assert.equal(r.layer.pitch, -1);
    assert.ok(reserved.includes("sound:blaster.fire"));
    assert.equal(soundLayerFrom(id)!.source, `lib:${id}`);
    assert.equal(soundLayerFrom("nope"), null);
    const unchanged = await useSoundFromLibrary({ id, set: "blaster", event: "fire2", role: "fire", namespace: ns, libraryCleared: true, pitch: 0 }, reserve);
    assert.ok(!unchanged.ok && /unchanged/.test(unchanged.error));
  });
});

// ---------------------------------------------------------------- PNG fixtures
const chunk = (type: string, data: Buffer) => { const b = Buffer.alloc(12 + data.length); b.writeUInt32BE(data.length, 0); b.write(type, 4, "latin1"); data.copy(b, 8); b.writeUInt32BE(crc32(b.subarray(4, 8 + data.length)), 8 + data.length); return b; };
const SIG = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
function pngOf(w: number, h: number, opts: { ct?: number; depth?: number; raw?: Buffer; extra?: Buffer[]; interlace?: number; plte?: Buffer; trns?: Buffer } = {}) {
  const ct = opts.ct ?? 6, depth = opts.depth ?? 8;
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = depth; ihdr[9] = ct; ihdr[12] = opts.interlace ?? 0;
  const ch = { 0: 1, 2: 3, 3: 1, 4: 2, 6: 4 }[ct]!; const stride = Math.ceil((w * ch * depth) / 8);
  const raw = opts.raw ?? Buffer.alloc(h * (stride + 1), 0);
  return Buffer.concat([SIG, chunk("IHDR", ihdr), ...(opts.extra ?? []), ...(opts.plte ? [chunk("PLTE", opts.plte)] : []), ...(opts.trns ? [chunk("tRNS", opts.trns)] : []), chunk("IDAT", deflateSync(raw)), chunk("IEND", Buffer.alloc(0))]);
}
const swordPng = encodePng(render(librarySpec(libraryTextures().find((i) => i.id === "sword_iron")!)!));
const withText = Buffer.concat([swordPng.subarray(0, 33), chunk("tEXt", Buffer.from("Comment\0secret author: someone@example.com")), chunk("eXIf", Buffer.from("MM\0*fake-exif")), swordPng.subarray(33)]);

describe("PNG upload validation", () => {
  it("a valid upload decodes, passes, and re-encodes to the same pixels", () => {
    const v = validateTextureUpload(swordPng);
    assert.ok(v.ok, !v.ok ? v.error : "");
    if (!v.ok) return;
    assert.equal(v.width, 16); assert.equal(v.alpha, "binary"); assert.equal(v.quality.verdict, "pass");
    assert.deepEqual(v.png, swordPng);
  });
  it("metadata is stripped: tEXt / eXIf are reported and absent from the stored PNG", () => {
    const v = validateTextureUpload(withText);
    assert.ok(v.ok);
    if (!v.ok) return;
    assert.deepEqual(v.stripped, ["tEXt", "eXIf"]);
    assert.ok(!v.png.includes(Buffer.from("tEXt")) && !v.png.includes(Buffer.from("secret")));
    assert.deepEqual(v.png, swordPng);
    assert.notEqual(v.originalSha256, v.sha256);
  });
  it("oversize files are refused before parsing", () => {
    const big = Buffer.concat([swordPng.subarray(0, 33), chunk("zTXt", Buffer.alloc(UPLOAD_LIMITS.maxBytes)), swordPng.subarray(33)]);
    const v = validateTextureUpload(big);
    assert.ok(!v.ok && v.code === "too_large");
  });
  it("bad dimensions: non-square, not an allowed size, and a huge declared size never inflates", () => {
    for (const [w, h] of [[16, 32], [20, 20], [128, 128], [50000, 50000]]) {
      const v = validateTextureUpload(pngOf(w, h, { raw: Buffer.alloc(10) }));
      assert.ok(!v.ok && v.code === "bad_dimensions", `${w}x${h}`);
    }
  });
  it("a decompression bomb (64x64 header, megabytes of image data) is stopped at the header's size", () => {
    const bomb = pngOf(64, 64, { raw: Buffer.alloc(8 * 1024 * 1024, 0) });
    assert.ok(bomb.length < UPLOAD_LIMITS.maxBytes, "the bomb itself is small");
    const v = validateTextureUpload(bomb);
    assert.ok(!v.ok && v.code === "decompression_bomb", JSON.stringify(v));
  });
  it("corrupt / unsupported files are refused with a reason", () => {
    const badCrc = Buffer.from(swordPng); badCrc[40] ^= 0xff;
    const cases: [Buffer, string][] = [
      [Buffer.from("GIF89a not a png at all, padded to be long enough........"), "not_png"],
      [badCrc, "bad_crc"],
      [pngOf(16, 16, { depth: 16, raw: Buffer.alloc(16 * (16 * 8 + 1)) }), "bad_depth"],
      [pngOf(16, 16, { interlace: 1 }), "interlaced"],
      [Buffer.concat([swordPng.subarray(0, 33), chunk("ABCD", Buffer.alloc(4)), swordPng.subarray(33)]), "bad_chunk"],
      [swordPng.subarray(0, swordPng.length - 12), "truncated"],
    ];
    for (const [b, code] of cases) { const d = decodePng(b, UPLOAD_LIMITS); assert.ok(!d.ok && d.code === code, `${code}: ${JSON.stringify(d)}`); }
  });
  it("pixel rules: semi-transparent pixels, photo-like colour counts and failing quality are refused", () => {
    const raw = Buffer.alloc(16 * (16 * 4 + 1));
    for (let y = 0; y < 16; y++) for (let x = 4; x < 12; x++) { const o = y * 65 + 1 + x * 4; raw[o] = 200; raw[o + 3] = 128; }
    assert.equal((validateTextureUpload(pngOf(16, 16, { raw })) as { code: string }).code, "translucent");
    const noisy = Buffer.alloc(64 * (64 * 4 + 1));
    for (let y = 0; y < 64; y++) for (let x = 0; x < 64; x++) { const o = y * 257 + 1 + x * 4; noisy[o] = (x * 4) & 255; noisy[o + 1] = (y * 4) & 255; noisy[o + 2] = (x * y) & 255; noisy[o + 3] = 255; }
    assert.equal((validateTextureUpload(pngOf(64, 64, { raw: noisy })) as { code: string }).code, "too_many_colours");
    const empty = validateTextureUpload(pngOf(16, 16));
    assert.ok(!empty.ok && empty.code === "quality");
  });
  it("palette PNGs (4-bit with tRNS) decode to the right pixels", () => {
    const raw = Buffer.alloc(16 * 9);
    for (let y = 0; y < 16; y++) for (let x = 0; x < 8; x++) raw[y * 9 + 1 + x] = (y > 3 && y < 12 && x > 1 && x < 6) ? 0x12 : 0x00;
    const d = decodePng(pngOf(16, 16, { ct: 3, depth: 4, raw, plte: Buffer.from([0, 0, 0, 20, 20, 30, 220, 60, 60]), trns: Buffer.from([0]) }), UPLOAD_LIMITS);
    assert.ok(d.ok);
    if (!d.ok) return;
    const at = (x: number, y: number) => [...d.raster.px.subarray((y * 16 + x) * 4, (y * 16 + x) * 4 + 4)];
    assert.deepEqual(at(0, 0), [0, 0, 0, 0]);
    assert.deepEqual(at(4, 5), [20, 20, 30, 255]);
    assert.deepEqual(at(5, 5), [220, 60, 60, 255]);
  });
});

describe("uploadTexture (fake store, storage and moderation)", () => {
  const mk = (over: Partial<UploadDeps> = {}) => {
    const recorded: unknown[] = [], stored: string[] = [];
    const d: UploadDeps = {
      storage: { put: async (key) => { stored.push(key); return { path: `mem/${key}` }; } },
      getProject: async (id) => (id === "cpA" ? { id, userId: "u1", headRevisionId: "rev1" } : id === "cpNew" ? { id, userId: "u1", headRevisionId: null } : null),
      recordAsset: async (_p, a) => { recorded.push(a); return { id: "asset1" }; },
      ...over,
    };
    return { d, recorded, stored };
  };
  it("top plan: stored content-addressed, recorded as origin upload with the reports and an 'unreviewed' stub verdict", async () => {
    const { d, recorded, stored } = mk();
    const r = await uploadTexture({ userId: "u1", projectId: "cpA", plan: "all", key: "my_sword", bytes: withText }, d);
    assert.ok(r.ok, !r.ok ? r.error : "");
    assert.equal(stored[0], `cyrus/uploads/cpA/${(r as { sha256: string }).sha256}.png`);
    const a = recorded[0] as { origin: string; kind: string; revisionId: string; provenance: { moderation: { status: string }; stripped: string[]; quality: { verdict: string } } };
    assert.equal(a.origin, "upload"); assert.equal(a.kind, "texture"); assert.equal(a.revisionId, "rev1");
    assert.equal(a.provenance.moderation.status, "unreviewed");
    assert.deepEqual(a.provenance.stripped, ["tEXt", "eXIf"]);
  });
  it("plan gate (Saka / free locked, unknown fails closed), ownership, revision and moderation refusals store nothing", async () => {
    for (const [plan, code] of [["saka", "asset_locked"], ["free", "asset_locked"], [null, "plan_unknown"]] as const) {
      const { d, stored } = mk();
      const r = await uploadTexture({ userId: "u1", projectId: "cpA", plan, key: "k1", bytes: swordPng }, d);
      assert.ok(!r.ok && r.code === code, String(plan)); assert.equal(stored.length, 0);
    }
    const { d, stored, recorded } = mk({ moderate: async () => ({ status: "rejected", reason: "not allowed", by: "test" }) });
    assert.equal(((await uploadTexture({ userId: "u2", projectId: "cpA", plan: "all", key: "k1", bytes: swordPng }, d)) as { code: string }).code, "not_found");
    assert.equal(((await uploadTexture({ userId: "u1", projectId: "cpNew", plan: "all", key: "k1", bytes: swordPng }, d)) as { code: string }).code, "no_revision");
    assert.equal(((await uploadTexture({ userId: "u1", projectId: "cpA", plan: "all", key: "k1", bytes: swordPng }, d)) as { code: string }).code, "moderation");
    assert.equal(((await uploadTexture({ userId: "u1", projectId: "cpA", plan: "all", key: "Bad Key", bytes: swordPng }, mk().d)) as { code: string }).code, "bad_request");
    assert.equal(stored.length + recorded.length, 0);
  });
});

