// Cyrus unified asset catalog (R1), pure tests (no DB, no network): realistic searches across sounds + textures,
// facets / pagination / similar, the browse gate matrix (plans x kinds x sources x signed-in), the catalog service
// with fake providers and plan lookup, user/project assets through a fake store, use-in-project namespacing, and
// PNG upload validation (valid, oversize, bad dimensions, decompression bomb, metadata stripped, ...).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { deflateSync } from "node:zlib";
import { crc32, encodePng } from "../lib/cyrus/textures/png";
import { render } from "../lib/cyrus/textures/render";
import { libraryTextures, librarySpec } from "../lib/cyrus/texture-library/library";
import { librarySounds } from "../lib/cyrus/sound/library";
import { builtinSoundAssets, builtinTextureAssets, SoundLibraryProvider, TextureLibraryProvider } from "../lib/cyrus/library/providers";
import { searchAssets, similarAssets, expandTerm } from "../lib/cyrus/library/search";
import { canBrowse } from "../lib/cyrus/library/gate";
import { browseLibrary, similarInLibrary, type CatalogDeps } from "../lib/cyrus/library/catalog";
import { userAssetProviders, latestRows, type UserAssetRow } from "../lib/cyrus/library/user-assets";
import { useSoundFromLibrary, useTextureFromLibrary, soundLayerFrom, type Reserve } from "../lib/cyrus/library/use-in-project";
import { decodePng } from "../lib/cyrus/library/png-decode";
import { uploadTexture, validateTextureUpload, UPLOAD_LIMITS, type UploadDeps } from "../lib/cyrus/library/upload";
import { LIBRARY_KINDS, LIBRARY_SOURCES, type LibraryAsset } from "../lib/cyrus/library/types";
import { namespaceFromSeed } from "../lib/cyrus/engine-core/identifiers";
import type { ModSpec } from "../lib/cyrus/engine-core/spec";

const ALL = [...builtinTextureAssets(), ...builtinSoundAssets()];
const top = (text: string, n = 10, kinds?: LibraryAsset["kind"][]) => searchAssets(ALL, { text, limit: n, ...(kinds ? { kinds } : {}) }).items;

describe("unified search: realistic queries", () => {
  it("'sword' -> swords first, then other blades; sounds join via synonyms (melee/whoosh)", () => {
    const r = searchAssets(ALL, { text: "sword", limit: 20 });
    assert.ok(r.items.slice(0, 6).every((a) => a.kind === "texture" && a.descriptors.template === "sword"), r.items.slice(0, 6).map((a) => a.id).join());
    assert.ok((r.facets.kind.sound ?? 0) > 0, "sword should also find melee / whoosh sounds");
  });
  it("'iron' -> iron materials (sword, ore, plate, ingot...)", () => {
    const ids = searchAssets(ALL, { text: "iron", limit: 200, kinds: ["texture"] }).items.map((a) => a.id);
    for (const id of ["sword_iron", "ore_iron", "metal_plate_iron", "ingot_iron", "helmet_iron"]) assert.ok(ids.includes(id), id);
    assert.ok(top("iron", 10, ["texture"]).every((a) => a.tags.includes("iron")));
  });
  it("'stone' -> stone blocks first", () => {
    const t = top("stone", 8, ["texture"]);
    assert.ok(t.every((a) => a.category === "blocks" || a.tags.includes("stone")), t.map((a) => a.id).join());
    assert.ok(t.some((a) => a.id === "cobble_stone"));
  });
  it("'gui button' -> buttons first (gui expands to the GUI family, button is exact)", () => {
    const t = top("gui button", 6, ["texture"]);
    assert.ok(t.length >= 6 && t.every((a) => a.subcategory === "button"), t.map((a) => a.id).join());
  });
  it("'potion' -> flasks, vials and bottles", () => {
    const t = searchAssets(ALL, { text: "potion", kinds: ["texture"], limit: 50 }).items;
    assert.ok(t.length >= 15 && t.slice(0, 15).every((a) => a.subcategory === "potion"));
  });
  it("'ore' -> the ore blocks (8 ramps), nothing unrelated above them", () => {
    const t = top("ore", 8, ["texture"]);
    assert.equal(t.filter((a) => a.descriptors.template === "ore").length, 8);
  });
  it("across kinds: 'gun' finds the handgun texture AND gunshot / reload sounds", () => {
    const r = searchAssets(ALL, { text: "gun", limit: 200 });
    assert.ok(r.items.some((a) => a.kind === "texture" && a.descriptors.template === "handgun"));
    assert.ok(r.items.some((a) => a.kind === "sound" && a.category === "weapons"));
    assert.ok(expandTerm("gun").includes("handgun") && expandTerm("gun").includes("gunshot"));
  });
  it("every query word must match; nonsense finds nothing", () => {
    assert.equal(searchAssets(ALL, { text: "sword zzqx" }).total, 0);
    assert.equal(searchAssets(ALL, { text: "" }).total, ALL.length);
  });
  it("filters, facets and pagination are consistent", () => {
    const all = searchAssets(ALL, { kinds: ["texture"], category: "blocks", limit: 200 });
    assert.equal(all.total, libraryTextures().filter((i) => i.category === "blocks").length);
    assert.equal(all.facets.category.blocks, all.total);
    const p1 = searchAssets(ALL, { kinds: ["texture"], category: "blocks", limit: 10, offset: 0 }).items.map((a) => a.ref);
    const p2 = searchAssets(ALL, { kinds: ["texture"], category: "blocks", limit: 10, offset: 10 }).items.map((a) => a.ref);
    assert.deepEqual([...p1, ...p2], all.items.slice(0, 20).map((a) => a.ref));
    const opaque = searchAssets(ALL, { kinds: ["texture"], descriptors: { transparency: ["opaque"] }, limit: 200 });
    assert.ok(opaque.total > 30 && opaque.items.every((a) => a.descriptors.transparency === "opaque"));
    assert.ok(Object.keys(all.facets.descriptors.material ?? {}).length > 5);
    const loud = searchAssets(ALL, { kinds: ["sound"], descriptors: { intensity: ["loud"] }, limit: 200 });
    assert.ok(loud.total > 0 && loud.items.every((a) => a.descriptors.intensity === "loud"));
  });
  it("similar to sword_iron: other melee weapons first, not just recolours", () => {
    const s = similarAssets("texture/builtin/sword_iron", ALL, 8);
    assert.ok(s.length >= 5);
    assert.ok(s.slice(0, 3).some((a) => a.descriptors.template !== "sword"));
    assert.ok(s.every((a) => a.kind === "texture" && a.useCases.includes("melee_weapon")));
    assert.deepEqual(similarAssets("texture/builtin/nope", ALL), []);
  });
  it("sound assets keep the library ledger and never expose the file name", () => {
    for (const a of builtinSoundAssets()) {
