describe("browse gate matrix", () => {
  const PLANS: [unknown, string][] = [["free", "free"], ["katara", "katara"], ["saka", "saka"], ["all", "all"], ["Yakko", "all"], ["platinum", "unknown"], [null, "unknown"], [undefined, "unknown"]];
  const expected = (plan: string, kind: string, source: string, signedIn: boolean): string => {
    if (!signedIn) return "sign_in";
    if (source === "project") return "ok";
    if (plan === "unknown") return "plan_unknown";
    const rank: Record<string, number> = { free: 0, katara: 1, saka: 2, all: 3 };
    return rank[plan] >= (kind === "sound" ? 2 : 3) ? "ok" : "asset_locked";
  };
  it("every plan x kind x source x signed-in combination", () => {
    let n = 0;
    for (const [raw, plan] of PLANS) for (const kind of LIBRARY_KINDS) for (const source of LIBRARY_SOURCES) for (const signedIn of [true, false]) {
      const d = canBrowse({ signedIn, plan: raw }, kind, source);
      assert.equal(d.ok ? "ok" : d.code, expected(plan, kind, source, signedIn), `${String(raw)} ${kind} ${source} ${signedIn}`);
      if (!d.ok && d.code === "asset_locked") assert.equal(d.needs, kind === "sound" ? "saka" : "all");
      n++;
    }
    assert.equal(n, PLANS.length * 3 * 3 * 2);
  });
});

