const deps = (plan: unknown, store = fakeStore): CatalogDeps => ({ providers: [SoundLibraryProvider, TextureLibraryProvider, ...userAssetProviders(store)], planOf: async () => { if (plan === "throw") throw new Error("billing down"); return plan; } });

describe("catalog service (fake providers and plan lookup)", () => {
