    assert.equal(r.facets.source.project, 1); // my_sword (latest row only)
    assert.equal(r.facets.source.user, 1); // banshee from the other project; the model row is skipped
    assert.deepEqual(r.denied.filter((d) => d.kind !== "model"), []);
  });
  it("Saka: sounds yes, textures no (denied with needs=all), own project textures still visible", async () => {
