    assert.ok((r.facets.kind.sound ?? 0) > 0);
    assert.deepEqual(r.items.filter((a) => a.kind === "texture").map((a) => a.source), ["project"]);
    assert.ok(r.denied.some((d) => d.kind === "texture" && d.source === "builtin" && d.code === "asset_locked" && d.needs === "all"));
  });
  it("free / Katara: only what is already in the project", async () => {
    for (const plan of ["free", "katara"]) {
      const r = await browseLibrary(deps(plan), { userId: "u1", projectId: "cpA", query: { limit: 200 } });
      assert.deepEqual([...new Set(r.items.map((a) => a.source))], ["project"], plan);
    }
  });
  it("unknown plan (lookup throws) fails closed; signed out sees nothing", async () => {
    const r = await browseLibrary(deps("throw"), { userId: "u1", projectId: "cpA" });
    assert.ok(r.items.every((a) => a.source === "project"));
    assert.ok(r.denied.some((d) => d.code === "plan_unknown"));
    const out = await browseLibrary(deps("all"), { userId: null, query: { text: "sword" } });
