describe("use in project (namespaced ids)", () => {
  const ns = namespaceFromSeed("cp-test-project");
  const reserved: string[] = [];
  const reserve: Reserve = async (kind, key) => { reserved.push(`${kind}:${key}`); return { fullId: kind === "sound" || kind === "model" ? `${ns}:${key}` : `${ns}.${key}` }; };
  it("instantiates a template with a chosen ramp and the mod's Style DNA, reserving <ns>:item/<key>", async () => {
    const r = await useTextureFromLibrary({ itemId: "sword_iron", ramps: { m: "emerald" }, dna: "pixel_bold", key: "jade_blade", namespace: ns }, reserve);
    assert.ok(r.ok, !r.ok ? r.error : "");
    if (!r.ok) return;
    assert.equal(r.spec.name, "jade_blade");
    assert.equal(r.identifier, `${ns}:item/jade_blade`);
    assert.equal(r.spec.palette.ol, "#0e0d12");
    assert.equal(r.spec.palette.m3, "#20a75b");
    assert.equal(r.slot.source, "library");
    assert.equal(r.provenance.library.templateId, "sword");
    assert.equal(r.provenance.ledger.original, true);
    assert.ok(reserved.includes("model:item/jade_blade"));
    const spec: Pick<ModSpec, "assets"> = { assets: [r.slot] };
    assert.equal(spec.assets[0].id, "jade_blade");
  });
  it("a block template reserves block/<key>; a custom DNA object works", async () => {
    const r = await useTextureFromLibrary({ templateId: "bricks", key: "red_wall", namespace: ns, dna: { id: "mod_dna", label: "Mod", outline: "none", light: "top_left", noise: "grit", rampSteps: 5, note: "" } }, reserve);
    assert.ok(r.ok && r.identifier === `${ns}:block/red_wall`);
    assert.ok(r.ok && r.spec.ops.some((o) => o.op === "noise"));
  });
  it("refuses bad keys, unknown items, wrong-family ramps, a foreign namespace and a mismatching reservation", async () => {
    assert.equal((await useTextureFromLibrary({ itemId: "sword_iron", key: "Bad Key", namespace: ns }, reserve)).ok, false);
    assert.equal((await useTextureFromLibrary({ itemId: "nope", key: "x1", namespace: ns }, reserve)).ok, false);
    assert.equal((await useTextureFromLibrary({ itemId: "sword_iron", ramps: { m: "oak" }, key: "x1", namespace: ns }, reserve)).ok, false);
    assert.equal((await useTextureFromLibrary({ itemId: "sword_iron", key: "x1", namespace: "minecraft" }, reserve)).ok, false);
    const other: Reserve = async (_k, key) => ({ fullId: `nx_00000000:${key}` });
    const r = await useTextureFromLibrary({ itemId: "sword_iron", key: "x2", namespace: ns }, other);
    assert.ok(!r.ok && /namespace/.test(r.error));
  });
  it("a library sound becomes a valid SoundSpec layer (transformed, licence rule) with <ns>:<set>.<event>", async () => {
    const id = librarySounds().find((s) => s.category === "weapons")!.id;
    assert.equal((await useSoundFromLibrary({ id, set: "blaster", event: "fire", role: "fire", namespace: ns, libraryCleared: false }, reserve)).ok, false);
    const r = await useSoundFromLibrary({ id, set: "blaster", event: "fire", role: "fire", subtitle: "Blaster fires", namespace: ns, libraryCleared: true }, reserve);
    assert.ok(r.ok, !r.ok ? r.error : "");
    if (!r.ok) return;
