// ---------------------------------------------------------------- PNG fixtures
const chunk = (type: string, data: Buffer) => { const b = Buffer.alloc(12 + data.length); b.writeUInt32BE(data.length, 0); b.write(type, 4, "latin1"); data.copy(b, 8); b.writeUInt32BE(crc32(b.subarray(4, 8 + data.length)), 8 + data.length); return b; };
const SIG = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
function pngOf(w: number, h: number, opts: { ct?: number; depth?: number; raw?: Buffer; extra?: Buffer[]; interlace?: number; plte?: Buffer; trns?: Buffer } = {}) {
  const ct = opts.ct ?? 6, depth = opts.depth ?? 8;
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = depth; ihdr[9] = ct; ihdr[12] = opts.interlace ?? 0;
  const ch = { 0: 1, 2: 3, 3: 1, 4: 2, 6: 4 }[ct]!; const stride = Math.ceil((w * ch * depth) / 8);
  const raw = opts.raw ?? Buffer.alloc(h * (stride + 1), 0);
  return Buffer.concat([SIG, chunk("IHDR", ihdr), ...(opts.extra ?? []), ...(opts.plte ? [chunk("PLTE", opts.plte)] : []), ...(opts.trns ? [chunk("tRNS", opts.trns)] : []), chunk("IDAT", deflateSync(raw)), chunk("IEND", Buffer.alloc(0))]);
}
const swordPng = encodePng(render(librarySpec(libraryTextures().find((i) => i.id === "sword_iron")!)!));
const withText = Buffer.concat([swordPng.subarray(0, 33), chunk("tEXt", Buffer.from("Comment\0secret author: someone@example.com")), chunk("eXIf", Buffer.from("MM\0*fake-exif")), swordPng.subarray(33)]);

describe("PNG upload validation", () => {
  it("a valid upload decodes, passes, and re-encodes to the same pixels", () => {
    const v = validateTextureUpload(swordPng);
    assert.ok(v.ok, !v.ok ? v.error : "");
    if (!v.ok) return;
    assert.equal(v.width, 16); assert.equal(v.alpha, "binary"); assert.equal(v.quality.verdict, "pass");
    assert.deepEqual(v.png, swordPng);
  });
  it("metadata is stripped: tEXt / eXIf are reported and absent from the stored PNG", () => {
    const v = validateTextureUpload(withText);
    assert.ok(v.ok);
    if (!v.ok) return;
    assert.deepEqual(v.stripped, ["tEXt", "eXIf"]);
    assert.ok(!v.png.includes(Buffer.from("tEXt")) && !v.png.includes(Buffer.from("secret")));
    assert.deepEqual(v.png, swordPng);
    assert.notEqual(v.originalSha256, v.sha256);
  });
  it("oversize files are refused before parsing", () => {
    const big = Buffer.concat([swordPng.subarray(0, 33), chunk("zTXt", Buffer.alloc(UPLOAD_LIMITS.maxBytes)), swordPng.subarray(33)]);
    const v = validateTextureUpload(big);
    assert.ok(!v.ok && v.code === "too_large");
  });
  it("bad dimensions: non-square, not an allowed size, and a huge declared size never inflates", () => {
    for (const [w, h] of [[16, 32], [20, 20], [128, 128], [50000, 50000]]) {
      const v = validateTextureUpload(pngOf(w, h, { raw: Buffer.alloc(10) }));
      assert.ok(!v.ok && v.code === "bad_dimensions", `${w}x${h}`);
    }
  });
  it("a decompression bomb (64x64 header, megabytes of image data) is stopped at the header's size", () => {
    const bomb = pngOf(64, 64, { raw: Buffer.alloc(8 * 1024 * 1024, 0) });
    assert.ok(bomb.length < UPLOAD_LIMITS.maxBytes, "the bomb itself is small");
    const v = validateTextureUpload(bomb);
    assert.ok(!v.ok && v.code === "decompression_bomb", JSON.stringify(v));
  });
  it("corrupt / unsupported files are refused with a reason", () => {
    const badCrc = Buffer.from(swordPng); badCrc[40] ^= 0xff;
    const cases: [Buffer, string][] = [
      [Buffer.from("GIF89a not a png at all, padded to be long enough........"), "not_png"],
      [badCrc, "bad_crc"],
      [pngOf(16, 16, { depth: 16, raw: Buffer.alloc(16 * (16 * 8 + 1)) }), "bad_depth"],
      [pngOf(16, 16, { interlace: 1 }), "interlaced"],
      [Buffer.concat([swordPng.subarray(0, 33), chunk("ABCD", Buffer.alloc(4)), swordPng.subarray(33)]), "bad_chunk"],
      [swordPng.subarray(0, swordPng.length - 12), "truncated"],
    ];
    for (const [b, code] of cases) { const d = decodePng(b, UPLOAD_LIMITS); assert.ok(!d.ok && d.code === code, `${code}: ${JSON.stringify(d)}`); }
  });
  it("pixel rules: semi-transparent pixels, photo-like colour counts and failing quality are refused", () => {
    const raw = Buffer.alloc(16 * (16 * 4 + 1));
    for (let y = 0; y < 16; y++) for (let x = 4; x < 12; x++) { const o = y * 65 + 1 + x * 4; raw[o] = 200; raw[o + 3] = 128; }
    assert.equal((validateTextureUpload(pngOf(16, 16, { raw })) as { code: string }).code, "translucent");
    const noisy = Buffer.alloc(64 * (64 * 4 + 1));
    for (let y = 0; y < 64; y++) for (let x = 0; x < 64; x++) { const o = y * 257 + 1 + x * 4; noisy[o] = (x * 4) & 255; noisy[o + 1] = (y * 4) & 255; noisy[o + 2] = (x * y) & 255; noisy[o + 3] = 255; }
    assert.equal((validateTextureUpload(pngOf(64, 64, { raw: noisy })) as { code: string }).code, "too_many_colours");
    const empty = validateTextureUpload(pngOf(16, 16));
    assert.ok(!empty.ok && empty.code === "quality");
  });
  it("palette PNGs (4-bit with tRNS) decode to the right pixels", () => {
    const raw = Buffer.alloc(16 * 9);
    for (let y = 0; y < 16; y++) for (let x = 0; x < 8; x++) raw[y * 9 + 1 + x] = (y > 3 && y < 12 && x > 1 && x < 6) ? 0x12 : 0x00;
    const d = decodePng(pngOf(16, 16, { ct: 3, depth: 4, raw, plte: Buffer.from([0, 0, 0, 20, 20, 30, 220, 60, 60]), trns: Buffer.from([0]) }), UPLOAD_LIMITS);
    assert.ok(d.ok);
    if (!d.ok) return;
    const at = (x: number, y: number) => [...d.raster.px.subarray((y * 16 + x) * 4, (y * 16 + x) * 4 + 4)];
    assert.deepEqual(at(0, 0), [0, 0, 0, 0]);
    assert.deepEqual(at(4, 5), [20, 20, 30, 255]);
    assert.deepEqual(at(5, 5), [220, 60, 60, 255]);
  });
});

describe("uploadTexture (fake store, storage and moderation)", () => {
  const mk = (over: Partial<UploadDeps> = {}) => {
