      recordAsset: async (_p, a) => { recorded.push(a); return { id: "asset1" }; },
      ...over,
    };
    return { d, recorded, stored };
  };
  it("top plan: stored content-addressed, recorded as origin upload with the reports and an 'unreviewed' stub verdict", async () => {
    const { d, recorded, stored } = mk();
    const r = await uploadTexture({ userId: "u1", projectId: "cpA", plan: "all", key: "my_sword", bytes: withText }, d);
    assert.ok(r.ok, !r.ok ? r.error : "");
    assert.equal(stored[0], `cyrus/uploads/cpA/${(r as { sha256: string }).sha256}.png`);
    const a = recorded[0] as { origin: string; kind: string; revisionId: string; provenance: { moderation: { status: string }; stripped: string[]; quality: { verdict: string } } };
    assert.equal(a.origin, "upload"); assert.equal(a.kind, "texture"); assert.equal(a.revisionId, "rev1");
    assert.equal(a.provenance.moderation.status, "unreviewed");
    assert.deepEqual(a.provenance.stripped, ["tEXt", "eXIf"]);
  });
  it("plan gate (Saka / free locked, unknown fails closed), ownership, revision and moderation refusals store nothing", async () => {
    for (const [plan, code] of [["saka", "asset_locked"], ["free", "asset_locked"], [null, "plan_unknown"]] as const) {
      const { d, stored } = mk();
      const r = await uploadTexture({ userId: "u1", projectId: "cpA", plan, key: "k1", bytes: swordPng }, d);
      assert.ok(!r.ok && r.code === code, String(plan)); assert.equal(stored.length, 0);
    }
    const { d, stored, recorded } = mk({ moderate: async () => ({ status: "rejected", reason: "not allowed", by: "test" }) });
    assert.equal(((await uploadTexture({ userId: "u2", projectId: "cpA", plan: "all", key: "k1", bytes: swordPng }, d)) as { code: string }).code, "not_found");
    assert.equal(((await uploadTexture({ userId: "u1", projectId: "cpNew", plan: "all", key: "k1", bytes: swordPng }, d)) as { code: string }).code, "no_revision");
    assert.equal(((await uploadTexture({ userId: "u1", projectId: "cpA", plan: "all", key: "k1", bytes: swordPng }, d)) as { code: string }).code, "moderation");
    assert.equal(((await uploadTexture({ userId: "u1", projectId: "cpA", plan: "all", key: "Bad Key", bytes: swordPng }, mk().d)) as { code: string }).code, "bad_request");
    assert.equal(stored.length + recorded.length, 0);
  });
});

