import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/**
 * Cyrus asset catalog (R1) against a THROWAWAY Postgres: the upload path with the real engine-core store
 * (CyrusProjectAsset on the head revision, content-addressed and idempotent), the Prisma UserAssetStore feeding the
 * catalog (project vs user source, other users' assets invisible), the browse gate with the REAL plan lookup
 * (tokens/access tierOf over CyrusPlan rows) as the injected host seam, and use-in-project with the real identifier
 * registry (namespaced, idempotent). No server, no model, no network.
 *
 * Opt-in and fail-closed: runs only when CYRUS_LIBRARY_DB_TEST=1 and DATABASE_URL is a node-2 agent database.
 *   devhost db push && devhost run --lock -- env CYRUS_LIBRARY_DB_TEST=1 npx tsx --test test/cyrus-library-db.test.ts
 */
const url = process.env.DATABASE_URL ?? "";
const safe = process.env.CYRUS_LIBRARY_DB_TEST === "1" && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?.*)?$/.test(url);
const skip = safe ? false : "set CYRUS_LIBRARY_DB_TEST=1 with a node-2 throwaway DATABASE_URL to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
const uniq = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
const uid = (n: string) => `cylib-${uniq}-${n}`;
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-library-db-"));

before(async () => {
  if (!safe) return;
  db = (await import("../lib/db.ts")).db;
  const end = new Date(Date.now() + 20 * 86400_000);
  for (const t of ["saka", "all"]) {
    await db.cyrusPlan.create({ data: { userId: uid(t), stripeCustomerId: `cus_${uid(t)}`, stripeSubscriptionId: `sub_${uid(t)}`, tier: t, priceTier: t, status: "active", currentPeriodEnd: end } });
  }
});
after(async () => {
  if (!safe) return;
  const projects = await db.cyrusProject.findMany({ where: { userId: { startsWith: `cylib-${uniq}-` } }, select: { id: true } });
  const ids = projects.map((p) => p.id);
  await db.cyrusIdentifier.deleteMany({ where: { projectId: { in: ids } } });
  await db.cyrusProjectAsset.deleteMany({ where: { projectId: { in: ids } } });
  await db.cyrusRevision.deleteMany({ where: { projectId: { in: ids } } });
  await db.cyrusProject.deleteMany({ where: { id: { in: ids } } });
  await db.cyrusPlan.deleteMany({ where: { userId: { startsWith: `cylib-${uniq}-` } } });
  await db.$disconnect();
  fs.rmSync(tmp, { recursive: true, force: true });
});

describe("Cyrus asset catalog (throwaway DB)", { skip }, () => {
  it("upload -> CyrusProjectAsset; catalog via the Prisma store and the real plan lookup; use-in-project with the real registry", async () => {
    const store = await import("../lib/cyrus/engine-core/store.ts");
    const { tierOf } = await import("../lib/cyrus/tokens/access.ts");
    const { uploadTexture } = await import("../lib/cyrus/library/upload.ts");
    const { prismaUserAssetStore } = await import("../lib/cyrus/library/user-store.ts");
    const { userAssetProviders } = await import("../lib/cyrus/library/user-assets.ts");
    const { SoundLibraryProvider, TextureLibraryProvider } = await import("../lib/cyrus/library/providers.ts");
    const { browseLibrary } = await import("../lib/cyrus/library/catalog.ts");
    const { useTextureFromLibrary } = await import("../lib/cyrus/library/use-in-project.ts");
    const { encodePng } = await import("../lib/cyrus/textures/png.ts");
    const { render } = await import("../lib/cyrus/textures/render.ts");
    const { libraryTextures, librarySpec } = await import("../lib/cyrus/texture-library/library.ts");

    const owner = uid("all");
    const p1 = await store.createProject({ userId: owner, game: "minecraft", title: "lib test 1" });
    const p2 = await store.createProject({ userId: owner, game: "minecraft", title: "lib test 2" });
    const pOther = await store.createProject({ userId: uid("saka"), game: "minecraft", title: "someone else" });
    for (const p of [p1, p2, pOther]) await store.addRevision(p.id, { kind: "generated", manifest: [], status: "passed" });

    const planOf = async (u: string) => tierOf(u);
    assert.equal(await planOf(owner), "all");
    const deps = {
      storage: { put: async (key: string, bytes: Buffer) => { const f = path.join(tmp, key); fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, bytes); return { path: f }; } },
      getProject: async (id: string) => db.cyrusProject.findUnique({ where: { id }, select: { id: true, userId: true, headRevisionId: true } }),
      recordAsset: (projectId: string, a: Parameters<typeof store.recordAsset>[1]) => store.recordAsset(projectId, a),
    };
    const png = encodePng(render(librarySpec(libraryTextures().find((i) => i.id === "gem_ruby")!)!));
    const up = await uploadTexture({ userId: owner, projectId: p1.id, plan: await planOf(owner), key: "my_gem", name: "My gem", bytes: png }, deps);
    assert.ok(up.ok, !up.ok ? up.error : "");
    const again = await uploadTexture({ userId: owner, projectId: p1.id, plan: await planOf(owner), key: "my_gem", bytes: png }, deps);
    assert.ok(again.ok && up.ok && again.assetId === up.assetId, "same content -> same row");
    const rows = await db.cyrusProjectAsset.findMany({ where: { projectId: p1.id } });
    assert.equal(rows.length, 1);
    assert.equal(rows[0].origin, "upload");
    assert.equal((rows[0].provenance as { moderation: { status: string } }).moderation.status, "unreviewed");
    assert.ok(fs.existsSync(rows[0].path!));
    // a Saka user may not upload a texture (real plan lookup)
    const locked = await uploadTexture({ userId: uid("saka"), projectId: pOther.id, plan: await planOf(uid("saka")), key: "x1", bytes: png }, deps);
    assert.ok(!locked.ok && locked.code === "asset_locked");

    const catalog = { providers: [SoundLibraryProvider, TextureLibraryProvider, ...userAssetProviders(prismaUserAssetStore)], planOf };
    const inP1 = await browseLibrary(catalog, { userId: owner, projectId: p1.id, query: { text: "my gem", limit: 5 } });
    assert.equal(inP1.items[0]?.ref, `texture/project/${p1.id}:my_gem`);
    const inP2 = await browseLibrary(catalog, { userId: owner, projectId: p2.id, query: { sources: ["user", "project"] } });
    assert.deepEqual(inP2.items.map((a) => a.ref), [`texture/user/${p1.id}:my_gem`]);
    const stranger = await browseLibrary(catalog, { userId: uid("saka"), projectId: pOther.id, query: { sources: ["user", "project"] } });
    assert.equal(stranger.total, 0, "another user's uploads are invisible");
    const saka = await browseLibrary(catalog, { userId: uid("saka"), query: { text: "sword" } });
    assert.ok(saka.items.every((a) => a.kind === "sound") && saka.denied.some((d) => d.kind === "texture" && d.code === "asset_locked"));
    const free = await browseLibrary(catalog, { userId: uid("nobody"), query: {} });
    assert.equal(free.total, 0);

    const reserve = (projectId: string) => async (kind: Parameters<typeof store.reserveIdentifier>[1], key: string) => store.reserveIdentifier(projectId, kind, key);
    const a = await useTextureFromLibrary({ itemId: "sword_iron", ramps: { m: "ruby" }, key: "red_blade", namespace: p1.namespace }, reserve(p1.id));
    const b = await useTextureFromLibrary({ itemId: "sword_iron", ramps: { m: "ruby" }, key: "red_blade", namespace: p1.namespace }, reserve(p1.id));
    const c = await useTextureFromLibrary({ itemId: "sword_iron", key: "red_blade", namespace: p2.namespace }, reserve(p2.id));
    assert.ok(a.ok && b.ok && c.ok);
    assert.equal(a.ok && a.identifier, `${p1.namespace}:item/red_blade`);
    assert.equal(c.ok && c.identifier, `${p2.namespace}:item/red_blade`);
    assert.equal((await store.listIdentifiers(p1.id)).filter((i) => i.key === "item/red_blade").length, 1, "reserving twice is idempotent");
    const wrong = await useTextureFromLibrary({ itemId: "sword_iron", key: "blue_blade", namespace: p1.namespace }, reserve(p2.id));
    assert.ok(!wrong.ok && /namespace/.test(wrong.error), "a reservation in another project's namespace is refused");
  });
});

